'use client';

import { buildInterventionDates, calendarDate, isCalendarDate, isClockTime } from '@/lib/intervention-dates';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { Plus, Filter, ChevronLeft, ChevronRight, CalendarDays, CalendarRange, Calendar, Loader2, Pencil, Trash2, X as XIcon, Droplets } from 'lucide-react';
import { Modal } from '@/components/ui/Modal';
import { InterventionForm } from '@/components/interventions/InterventionForm';
import { InterventionDetailSheet } from '@/components/calendar/InterventionDetailSheet';
import { CutoffNoticeSheet } from '@/components/calendar/CutoffNoticeSheet';
import { TimeGridView, TECHNICIAN_COLORS } from '@/components/calendar/TimeGridView';
import type { LeaveEntry, BirthdayEntry, ReminderEntry, SelectedSlot } from '@/components/calendar/TimeGridView';
import { getApprovedLeaves } from '@/lib/leave-utils';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { sendPush } from '@/lib/send-push';
import {
  format, startOfMonth, endOfMonth, startOfWeek, endOfWeek, startOfDay, endOfDay,
  eachDayOfInterval, isSameMonth, isSameDay, isToday, addWeeks, subWeeks, addDays,
  subDays, isWithinInterval,
} from 'date-fns';
import { fr } from 'date-fns/locale';

type CalendarView = 'month' | 'week' | 'day';
type InterventionTypeFilter = 'all' | 'depannage' | 'chantier' | 'maintenance';

interface Intervention {
  id: string; title: string; description: string | null; address: string;
  date_planned: string | null; date_end: string | null; estimated_duration_minutes: number; status: string;
  priority: number; technician_id: string | null; regie_id: string | null;
  client_info: { name?: string; phone?: string } | null; work_order_number: string | null;
  intervention_type?: 'depannage' | 'chantier' | null;
  maintenance_contract_id?: string | null;
  technician?: { id: string; first_name: string | null; last_name: string | null; calendar_color?: string | null } | null;
}

interface Technician { id: string; first_name: string | null; last_name: string | null; email: string; intervention_type_preference?: string | null; }
interface Regie { id: string; name: string; }

const UNASSIGNED_COLOR = '#9CA3AF';

const VIEW_TABS: { value: CalendarView; label: string; icon: typeof CalendarDays }[] = [
  { value: 'month', label: 'Mois', icon: CalendarDays },
  { value: 'week', label: 'Semaine', icon: CalendarRange },
  { value: 'day', label: 'Jour', icon: Calendar },
];

export default function CalendarPage() {
  const [view, setView] = useState<CalendarView>('week');
  const [typeFilter, setTypeFilter] = useState<InterventionTypeFilter>('all');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [interventions, setInterventions] = useState<Intervention[]>([]);
  const [leaves, setLeaves] = useState<LeaveEntry[]>([]);
  const [birthdays, setBirthdays] = useState<BirthdayEntry[]>([]);
  const [reminders, setReminders] = useState<ReminderEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [selectedIntervention, setSelectedIntervention] = useState<Intervention | null>(null);
  const [detailIntervention, setDetailIntervention] = useState<Intervention | null>(null);
  // Leave popup state
  const [selectedLeave, setSelectedLeave] = useState<LeaveEntry & { id?: string } | null>(null);
  const [isEditingLeave, setIsEditingLeave] = useState(false);
  const [editLeaveStart, setEditLeaveStart] = useState('');
  const [editLeaveEnd, setEditLeaveEnd] = useState('');
  const [isDeletingLeave, setIsDeletingLeave] = useState(false);
  const [leaveProcessing, setLeaveProcessing] = useState(false);
  // Cutoff reminder sheet state
  const [selectedReminder, setSelectedReminder] = useState<ReminderEntry | null>(null);
  const supabase = createClient();

  const getDateRange = useCallback(() => {
    switch (view) {
      case 'month': { const s = startOfWeek(startOfMonth(currentDate), { weekStartsOn: 1 }); const e = endOfWeek(endOfMonth(currentDate), { weekStartsOn: 1 }); return { start: s, end: e }; }
      case 'week': { const s = startOfWeek(currentDate, { weekStartsOn: 1 }); const e = endOfWeek(currentDate, { weekStartsOn: 1 }); return { start: s, end: e }; }
      case 'day': return { start: startOfDay(currentDate), end: endOfDay(currentDate) };
    }
  }, [view, currentDate]);

  const fetchInterventions = useCallback(async () => {
    setIsLoading(true);
    const { start, end } = getDateRange();
    // Fetch interventions: date_planned in range OR date_end overlaps range (multi-day chantiers)
    const { data } = await supabase.from('interventions').select(`id, title, description, address, date_planned, date_end, estimated_duration_minutes, status, priority, technician_id, regie_id, client_info, work_order_number, intervention_type, maintenance_contract_id, technician:users!interventions_technician_id_fkey(id, first_name, last_name, calendar_color)`).or(`and(date_planned.gte.${start.toISOString()},date_planned.lte.${end.toISOString()}),and(date_planned.lte.${end.toISOString()},date_end.gte.${start.toISOString()})`).order('date_planned', { ascending: true });
    if (data) setInterventions(data as Intervention[]);
    const sd = format(start, 'yyyy-MM-dd'); const ed = format(end, 'yyyy-MM-dd');
    const { data: leavesData } = await supabase.from('leave_requests').select(`id, technician_id, start_date, end_date, technician:users!leave_requests_technician_id_fkey(first_name, last_name)`).eq('status', 'approved').lte('start_date', ed).gte('end_date', sd);
    if (leavesData) setLeaves(leavesData as (LeaveEntry & { id: string })[]);

    // Fetch birthdays
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: usersData } = await (supabase as any)
      .from('users')
      .select('id, first_name, last_name, birth_date')
      .not('birth_date', 'is', null)
      .eq('is_active', true);

    if (usersData) {
      const currentYear = start.getFullYear();
      const entries: BirthdayEntry[] = [];
      for (const u of usersData as { id: string; first_name: string; last_name: string; birth_date: string }[]) {
        const [, month, day] = u.birth_date.split('-');
        const bdThisYear = `${currentYear}-${month}-${day}`;
        entries.push({ user_id: u.id, first_name: u.first_name, last_name: u.last_name, date: bdThisYear });
      }
      setBirthdays(entries);
    }

    // Fetch reminders
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: remindersData } = await (supabase as any)
      .from('intervention_reminders')
      .select('id, intervention_id, user_id, reminder_date, message, completed, technician:users!intervention_reminders_user_id_fkey(first_name, last_name)')
      .gte('reminder_date', sd)
      .lte('reminder_date', ed)
      .eq('completed', false);
    if (remindersData) setReminders(remindersData as ReminderEntry[]);

    setIsLoading(false);
  }, [view, currentDate]);

  useEffect(() => { fetchInterventions(); }, [fetchInterventions]);

  const navigatePrevious = () => { switch (view) { case 'month': setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1)); break; case 'week': setCurrentDate(subWeeks(currentDate, 1)); break; case 'day': setCurrentDate(subDays(currentDate, 1)); break; } };
  const navigateNext = () => { switch (view) { case 'month': setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1)); break; case 'week': setCurrentDate(addWeeks(currentDate, 1)); break; case 'day': setCurrentDate(addDays(currentDate, 1)); break; } };
  const goToToday = () => setCurrentDate(new Date());

  const navigationTitle = useMemo(() => {
    switch (view) {
      case 'month': return format(currentDate, 'MMMM yyyy', { locale: fr });
      case 'week': { const ws = startOfWeek(currentDate, { weekStartsOn: 1 }); const we = endOfWeek(currentDate, { weekStartsOn: 1 }); return `${format(ws, 'd MMM', { locale: fr })} – ${format(we, 'd MMM yyyy', { locale: fr })}`; }
      case 'day': return format(currentDate, 'EEEE d MMMM yyyy', { locale: fr });
    }
  }, [view, currentDate]);

  const handleLeaveClick = (leave: LeaveEntry) => {
    setSelectedLeave(leave as LeaveEntry & { id?: string });
    setIsEditingLeave(false);
    setIsDeletingLeave(false);
  };

  const handleEditLeave = async () => {
    if (!selectedLeave || !(selectedLeave as { id?: string }).id) return;
    setLeaveProcessing(true);
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any).from('leave_requests').update({ start_date: editLeaveStart, end_date: editLeaveEnd }).eq('id', (selectedLeave as { id: string }).id);
      if (error) throw new Error(error.message);
      toast.success('Congé modifié');
      setSelectedLeave(null);
      fetchInterventions();
    } catch { toast.error('Erreur lors de la modification'); }
    finally { setLeaveProcessing(false); }
  };

  const handleDeleteLeave = async () => {
    if (!selectedLeave || !(selectedLeave as { id?: string }).id) return;
    setLeaveProcessing(true);
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any).from('leave_requests').delete().eq('id', (selectedLeave as { id: string }).id);
      if (error) throw new Error(error.message);
      toast.success('Congé annulé et supprimé');
      setSelectedLeave(null);
      fetchInterventions();
    } catch { toast.error('Erreur lors de la suppression'); }
    finally { setLeaveProcessing(false); }
  };

  const handleInterventionClick = (iv: Intervention) => setDetailIntervention(iv);
  const handleReminderClick = (r: ReminderEntry) => setSelectedReminder(r);
  const handleOpenInterventionFromReminder = async (interventionId: string) => {
    // Try to find in current state; fallback to fetching
    const existing = interventions.find(iv => iv.id === interventionId);
    if (existing) {
      setSelectedReminder(null);
      setDetailIntervention(existing);
      return;
    }
    const { data } = await supabase
      .from('interventions')
      .select(`id, title, description, address, date_planned, date_end, estimated_duration_minutes, status, priority, technician_id, regie_id, client_info, work_order_number, intervention_type, technician:users!interventions_technician_id_fkey(id, first_name, last_name, calendar_color)`)
      .eq('id', interventionId)
      .single();
    if (data) {
      setSelectedReminder(null);
      setDetailIntervention(data as Intervention);
    }
  };
  const handleEditFromDetail = () => { if (detailIntervention) { setSelectedIntervention(detailIntervention); setDetailIntervention(null); setIsEditModalOpen(true); } };
  const handleCreateSuccess = () => { setIsCreateModalOpen(false); fetchInterventions(); };
  const handleEditSuccess = () => { setIsEditModalOpen(false); setSelectedIntervention(null); fetchInterventions(); };
  const switchToDay = (date: Date) => { setCurrentDate(date); setView('day'); };

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(currentDate);
  const calendarStart = startOfWeek(monthStart, { weekStartsOn: 1 });
  const calendarEnd = endOfWeek(monthEnd, { weekStartsOn: 1 });
  const calendarDays = eachDayOfInterval({ start: calendarStart, end: calendarEnd });
  const filteredInterventions = useMemo(() => {
    let result = interventions.filter(iv => iv.status !== 'cancelled' && iv.status !== 'annule');
    if (typeFilter === 'maintenance') {
      result = result.filter(iv => !!iv.maintenance_contract_id);
    } else if (typeFilter !== 'all') {
      result = result.filter(iv => iv.intervention_type === typeFilter && !iv.maintenance_contract_id);
    }
    return result;
  }, [interventions, typeFilter]);

  // Technician color map for month view — use stored calendar_color, fallback to palette
  const techColorMap = useMemo(() => {
    const uniqueIds = Array.from(new Set(interventions.map((iv) => iv.technician_id).filter(Boolean))) as string[];
    uniqueIds.sort();
    const map: Record<string, string> = {};
    let fallbackIdx = 0;
    uniqueIds.forEach((id) => {
      const iv = interventions.find((i) => i.technician_id === id);
      const storedColor = iv?.technician?.calendar_color;
      map[id] = storedColor || TECHNICIAN_COLORS[fallbackIdx++ % TECHNICIAN_COLORS.length];
    });
    return map;
  }, [interventions]);

  const getTechColor = (techId: string | null): string => {
    if (!techId) return UNASSIGNED_COLOR;
    return techColorMap[techId] || UNASSIGNED_COLOR;
  };

  // Unique technicians for legend
  const uniqueTechnicians = useMemo(() => {
    const seen = new Map<string, { id: string; name: string; color: string }>();
    interventions.forEach((iv) => {
      if (iv.technician_id && iv.technician && !seen.has(iv.technician_id)) {
        const name = [iv.technician.first_name, iv.technician.last_name].filter(Boolean).join(' ') || '?';
        seen.set(iv.technician_id, { id: iv.technician_id, name, color: techColorMap[iv.technician_id] || UNASSIGNED_COLOR });
      }
    });
    return Array.from(seen.values());
  }, [interventions, techColorMap]);

  const getIvsForDay = (date: Date) => filteredInterventions.filter((iv) => {
    if (!iv.date_planned) return false;
    // Multi-day chantier: show on all days between date_planned and date_end
    if (iv.date_end && iv.intervention_type === 'chantier') {
      const start = new Date(iv.date_planned);
      const end = new Date(iv.date_end);
      return date >= startOfDay(start) && date <= endOfDay(end);
    }
    return isSameDay(new Date(iv.date_planned), date);
  });
  const getLeavesForDay = (day: Date): LeaveEntry[] => leaves.filter((l) => { const s = new Date(l.start_date + 'T00:00:00'); const e = new Date(l.end_date + 'T23:59:59'); return isWithinInterval(day, { start: s, end: e }); });
  const getBirthdaysForDay = (day: Date): BirthdayEntry[] => birthdays.filter((b) => isSameDay(new Date(b.date + 'T00:00:00'), day));
  const cancelledInterventionIds = useMemo(() => new Set(interventions.filter(iv => iv.status === 'cancelled' || iv.status === 'annule').map(iv => iv.id)), [interventions]);
  const activeReminders = useMemo(() => reminders.filter(r => !cancelledInterventionIds.has(r.intervention_id)), [reminders, cancelledInterventionIds]);
  const getRemindersForDay = (day: Date): ReminderEntry[] => activeReminders.filter((r) => isSameDay(new Date(r.reminder_date + 'T00:00:00'), day));
  const getTechInitials = (t: Intervention['technician']) => t ? ((t.first_name?.[0] || '') + (t.last_name?.[0] || '')).toUpperCase() || '?' : null;
  const getTypeEmoji = (iv: Intervention) => {
    if (iv.maintenance_contract_id) return '🔩';
    if (iv.intervention_type === 'chantier') return '🏗️';
    return '🔧';
  };
  const getTechName = (t: LeaveEntry['technician']) => { if (!t) return '?'; if (t.first_name && t.last_name) return `${t.first_name} ${t.last_name}`; return t.first_name || t.last_name || '?'; };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div><p className="text-gray-500">Planification et vue d&apos;ensemble des interventions</p></div>
        <div className="flex items-center gap-2">
          <button className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg transition-colors"><Filter className="w-4 h-4" />Filtrer</button>
          <button onClick={() => setIsCreateModalOpen(true)} className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors shadow-sm"><Plus className="w-4 h-4" />Nouvelle intervention</button>
        </div>
      </div>

      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <div className="p-4 border-b border-gray-100 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="flex gap-1 bg-gray-100 p-1 rounded-lg">
              {VIEW_TABS.map((tab) => { const Icon = tab.icon; const isActive = view === tab.value; return (<button key={tab.value} onClick={() => setView(tab.value)} className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium rounded-md transition-all ${isActive ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}><Icon className="w-4 h-4" />{tab.label}</button>); })}
            </div>
            <div className="flex gap-1 bg-gray-100 p-0.5 rounded-lg">
              {([
                { value: 'all' as const, label: 'Tout', color: 'text-gray-900', activeBg: 'bg-white' },
                { value: 'depannage' as const, label: '🔧 Dépannage', color: 'text-red-700', activeBg: 'bg-red-50' },
                { value: 'chantier' as const, label: '🏗️ Chantier', color: 'text-blue-700', activeBg: 'bg-blue-50' },
                { value: 'maintenance' as const, label: '🔩 Maintenance', color: 'text-violet-700', activeBg: 'bg-violet-50' },
              ]).map((tab) => (
                <button key={tab.value} onClick={() => setTypeFilter(tab.value)} className={`px-2.5 py-1 text-xs font-medium rounded-md transition-all ${typeFilter === tab.value ? `${tab.activeBg} ${tab.color} shadow-sm` : 'text-gray-500 hover:text-gray-700'}`}>{tab.label}</button>
              ))}
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button onClick={navigatePrevious} className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition-colors"><ChevronLeft className="w-5 h-5" /></button>
            <button onClick={goToToday} className="px-3 py-1.5 text-sm font-medium text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">Aujourd&apos;hui</button>
            <button onClick={navigateNext} className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-lg transition-colors"><ChevronRight className="w-5 h-5" /></button>
            <h2 className="text-lg font-semibold text-gray-900 capitalize ml-2">{navigationTitle}</h2>
          </div>
        </div>

        <div className="p-4">
          {isLoading ? (<div className="flex items-center justify-center py-20"><div className="w-8 h-8 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin" /></div>) : (<>
            {view === 'month' && (<>
              <div className="grid grid-cols-7 mb-2">{['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map((d) => (<div key={d} className="py-2 text-center text-xs font-semibold text-gray-500 uppercase">{d}</div>))}</div>
              <div className="grid grid-cols-7 gap-px bg-gray-200 rounded-lg overflow-hidden">
                {calendarDays.map((day, idx) => {
                  const dayIvs = getIvsForDay(day); const dayLeaves = getLeavesForDay(day); const dayBirthdays = getBirthdaysForDay(day); const dayReminders = getRemindersForDay(day);
                  const isCur = isSameMonth(day, currentDate); const isT = isToday(day);
                  const MAX = 2; const overflow = dayIvs.length - MAX;
                  return (<div key={idx} className={`bg-white min-h-[100px] p-2 ${!isCur ? 'bg-gray-50' : ''}`}>
                    <div className={`text-sm font-medium mb-1 w-7 h-7 flex items-center justify-center rounded-full ${isT ? 'bg-blue-600 text-white' : isCur ? 'text-gray-900' : 'text-gray-400'}`}>{format(day, 'd')}</div>
                    {dayBirthdays.map((b) => (<div key={`b-${b.user_id}`} className="w-full text-left text-xs px-1.5 py-1 rounded-md bg-violet-200 text-violet-800 font-semibold mb-0.5 truncate border border-violet-300">🎂 {b.first_name}</div>))}
                    {dayLeaves.map((l, i) => (<div key={`l-${l.technician_id}-${i}`} className="w-full text-left text-xs px-1.5 py-1 rounded-md bg-emerald-200 text-emerald-800 font-semibold mb-0.5 truncate border border-emerald-400">🌴 {getTechName(l.technician)}</div>))}
                    {dayReminders.map((rem) => (<button type="button" key={`r-${rem.id}`} onClick={() => handleReminderClick(rem)} className="w-full text-left text-xs px-1.5 py-1 rounded-md bg-orange-200 text-orange-800 font-semibold mb-0.5 truncate border border-orange-400 hover:bg-orange-300 transition-colors cursor-pointer" title={rem.message}>🔔 {rem.message.length > 15 ? rem.message.slice(0, 15) + '…' : rem.message}</button>))}
                    <div className="space-y-1">
                      {dayIvs.slice(0, MAX).map((iv) => (<button key={iv.id} onClick={() => handleInterventionClick(iv)} className="w-full text-left text-xs px-1.5 py-1 rounded text-white transition-colors cursor-pointer hover:opacity-90" style={{ backgroundColor: getTechColor(iv.technician_id) }} title={`${iv.intervention_type === 'chantier' ? '[Chantier]' : '[Dépannage]'} ${iv.work_order_number || iv.title}`}><div className="flex items-center gap-1"><span className="text-[10px]">{getTypeEmoji(iv)}</span>{iv.technician && <span className="flex-shrink-0 w-4 h-4 rounded-full bg-white/30 flex items-center justify-center text-[9px] font-bold">{getTechInitials(iv.technician)}</span>}<span className="truncate flex-1">{iv.work_order_number || iv.title}</span></div></button>))}
                      {overflow > 0 && (<button onClick={() => switchToDay(day)} className="w-full text-left text-xs text-blue-600 hover:text-blue-800 font-medium px-1.5 py-0.5 hover:bg-blue-50 rounded transition-colors">+ {overflow} autre{overflow > 1 ? 's' : ''}</button>)}
                    </div>
                  </div>);
                })}
              </div>
            </>)}
            {view === 'week' && <TimeGridView mode="week" currentDate={currentDate} interventions={filteredInterventions} leaves={leaves} birthdays={birthdays} reminders={activeReminders} onInterventionClick={handleInterventionClick} onLeaveClick={handleLeaveClick} onReminderClick={handleReminderClick} />}
            {view === 'day' && <TimeGridView mode="day" currentDate={currentDate} interventions={filteredInterventions} leaves={leaves} birthdays={birthdays} reminders={activeReminders} onInterventionClick={handleInterventionClick} onLeaveClick={handleLeaveClick} onReminderClick={handleReminderClick} />}
          </>)}
        </div>

        <div className="px-4 pb-4">
          <div className="flex flex-wrap items-center gap-4 text-xs">
            {uniqueTechnicians.map((t) => (
              <div key={t.id} className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: t.color }} /><span className="text-gray-600">{t.name}</span></div>
            ))}
            <div className="flex items-center gap-1.5"><span className="w-3 h-3 rounded" style={{ backgroundColor: UNASSIGNED_COLOR }} /><span className="text-gray-600">Non assigné</span></div>
            <div className="border-l border-gray-300 h-4" />
            <div className="flex items-center gap-1.5"><span className="text-gray-600">🔧 Dépannage</span></div>
            <div className="flex items-center gap-1.5"><span className="text-gray-600">🏗️ Chantier</span></div>
            <div className="flex items-center gap-1.5"><span className="text-gray-600">🔩 Maintenance</span></div>
            <div className="border-l border-gray-300 h-4" />
            <div className="flex items-center gap-1.5"><span className="w-3 h-3 rounded bg-emerald-100 border border-emerald-300" /><span className="text-gray-600">🌴 Congé</span></div>
            <div className="flex items-center gap-1.5"><span className="w-3 h-3 rounded bg-violet-100 border border-violet-300" /><span className="text-gray-600">🎂 Anniversaire</span></div>
            <div className="flex items-center gap-1.5"><span className="w-3 h-3 rounded bg-orange-100 border border-orange-300" /><span className="text-gray-600">🔔 Rappel</span></div>
            <div className="flex items-center gap-1.5"><span className="w-8 h-3 rounded bg-gray-100 border border-dashed border-gray-300" /><span className="text-gray-600">🍽️ Pause midi</span></div>
          </div>
        </div>
      </div>

      {/* MODAL CRÉATION — Split view Formulaire + Calendrier */}
      <Modal isOpen={isCreateModalOpen} onClose={() => setIsCreateModalOpen(false)} title="Nouvelle intervention" size="full">
        <CreateInterventionSplitView onSuccess={handleCreateSuccess} onCancel={() => setIsCreateModalOpen(false)} />
      </Modal>

      <Modal isOpen={isEditModalOpen} onClose={() => { setIsEditModalOpen(false); setSelectedIntervention(null); }} title="Modifier l'intervention" size="lg">
        {selectedIntervention && <InterventionForm intervention={selectedIntervention} onSuccess={handleEditSuccess} onCancel={() => { setIsEditModalOpen(false); setSelectedIntervention(null); }} onDelete={() => { setIsEditModalOpen(false); setSelectedIntervention(null); }} />}
      </Modal>

      <InterventionDetailSheet intervention={detailIntervention} onClose={() => setDetailIntervention(null)} onEdit={handleEditFromDetail} />

      <CutoffNoticeSheet
        reminder={selectedReminder}
        onClose={() => setSelectedReminder(null)}
        onOpenIntervention={handleOpenInterventionFromReminder}
        onChanged={fetchInterventions}
      />

      {/* Leave popup */}
      {selectedLeave && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40" onClick={() => setSelectedLeave(null)}>
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm mx-4" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100">
              <h3 className="font-semibold text-gray-900 flex items-center gap-2">🌴 Congé</h3>
              <button onClick={() => setSelectedLeave(null)} className="p-1.5 hover:bg-gray-100 rounded-lg"><XIcon className="w-4 h-4 text-gray-400" /></button>
            </div>
            <div className="px-5 py-4 space-y-3">
              <div>
                <p className="text-xs text-gray-500">Technicien</p>
                <p className="text-sm font-semibold text-gray-900">{getTechName(selectedLeave.technician)}</p>
              </div>
              <div className="flex gap-4">
                <div><p className="text-xs text-gray-500">Du</p><p className="text-sm font-medium">{format(new Date(selectedLeave.start_date + 'T00:00:00'), 'd MMM yyyy', { locale: fr })}</p></div>
                <div><p className="text-xs text-gray-500">Au</p><p className="text-sm font-medium">{format(new Date(selectedLeave.end_date + 'T00:00:00'), 'd MMM yyyy', { locale: fr })}</p></div>
              </div>

              {isEditingLeave && (
                <div className="space-y-2 pt-2 border-t border-gray-100">
                  <p className="text-sm font-medium text-gray-700">Modifier les dates</p>
                  <div className="grid grid-cols-2 gap-2">
                    <input type="date" value={editLeaveStart} onChange={(e) => setEditLeaveStart(e.target.value)} className="h-9 px-3 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500" />
                    <input type="date" value={editLeaveEnd} onChange={(e) => setEditLeaveEnd(e.target.value)} className="h-9 px-3 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500" />
                  </div>
                </div>
              )}

              {isDeletingLeave && (
                <div className="bg-red-50 rounded-lg p-3 border border-red-200">
                  <p className="text-sm text-red-800">Supprimer ce congé ?</p>
                </div>
              )}
            </div>
            <div className="flex items-center justify-end gap-2 px-5 py-4 border-t border-gray-100">
              {!isEditingLeave && !isDeletingLeave && (
                <>
                  <button onClick={() => { setIsEditingLeave(true); setEditLeaveStart(selectedLeave.start_date); setEditLeaveEnd(selectedLeave.end_date); }} className="inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg"><Pencil className="w-3.5 h-3.5" />Modifier</button>
                  <button onClick={() => setIsDeletingLeave(true)} className="inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-red-600 bg-white border border-gray-200 hover:bg-red-50 rounded-lg"><Trash2 className="w-3.5 h-3.5" />Annuler</button>
                </>
              )}
              {isEditingLeave && (
                <>
                  <button onClick={() => setIsEditingLeave(false)} className="px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg">Retour</button>
                  <button onClick={handleEditLeave} disabled={leaveProcessing} className="inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg disabled:opacity-50">{leaveProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Pencil className="w-3.5 h-3.5" />}Enregistrer</button>
                </>
              )}
              {isDeletingLeave && (
                <>
                  <button onClick={() => setIsDeletingLeave(false)} className="px-3 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg">Non, garder</button>
                  <button onClick={handleDeleteLeave} disabled={leaveProcessing} className="inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium text-white bg-red-600 hover:bg-red-700 rounded-lg disabled:opacity-50">{leaveProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-3.5 h-3.5" />}Supprimer</button>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// SPLIT VIEW pour création: Formulaire + TimeGridView calendrier semaine
// ═══════════════════════════════════════════════════════════════════════════════

interface ClientOption {
  id: string;
  first_name: string | null;
  last_name: string | null;
  company_name: string | null;
  phone: string | null;
  address: string | null;
  regie_id: string | null;
}

function CreateInterventionSplitView({ onSuccess, onCancel }: { onSuccess: () => void; onCancel: () => void }) {
  const [isLoading, setIsLoading] = useState(false);
  const [calendarWeek, setCalendarWeek] = useState(new Date());
  const [calendarInterventions, setCalendarInterventions] = useState<Intervention[]>([]);
  const [calendarLeaves, setCalendarLeaves] = useState<LeaveEntry[]>([]);
  const [calendarBirthdays, setCalendarBirthdays] = useState<BirthdayEntry[]>([]);
  const [technicians, setTechnicians] = useState<Technician[]>([]);
  const [regies, setRegies] = useState<Regie[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [clientSuggestions, setClientSuggestions] = useState<ClientOption[]>([]);
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [showClientDropdown, setShowClientDropdown] = useState(false);
  const [formData, setFormData] = useState({
    title: '', description: '', address: '', date_planned: '', time_planned: '',
    estimated_duration_minutes: 60, priority: 0,
    technician_id: '', regie_id: '', work_order_number: '', client_name: '', client_phone: '',
    intervention_type: 'depannage', keys_info: '', date_end: '',
  });
  const [cutoffEnabled, setCutoffEnabled] = useState(false);
  const [cutoffDate, setCutoffDate] = useState('');
  const supabase = createClient();

  useEffect(() => {
    const fetchRefs = async () => {
      const { data: t } = await supabase.from('users').select('id, first_name, last_name, email, intervention_type_preference').eq('role', 'technician').order('last_name');
      if (t) setTechnicians(t);
      const { data: r } = await supabase.from('regies').select('id, name').eq('is_active', true).order('name');
      if (r) setRegies(r);
    };
    fetchRefs();
  }, []);

  const weekStart = useMemo(() => startOfWeek(calendarWeek, { weekStartsOn: 1 }), [calendarWeek]);
  const weekEnd = useMemo(() => endOfWeek(calendarWeek, { weekStartsOn: 1 }), [calendarWeek]);

  const fetchCalendarData = useCallback(async () => {
    const sd = format(weekStart, 'yyyy-MM-dd');
    const ed = format(weekEnd, 'yyyy-MM-dd');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let q = (supabase as any).from('interventions')
      .select('id, title, description, address, date_planned, date_end, estimated_duration_minutes, status, priority, technician_id, regie_id, client_info, work_order_number, intervention_type, technician:users!interventions_technician_id_fkey(id, first_name, last_name)')
      .or(`and(date_planned.gte.${weekStart.toISOString()},date_planned.lte.${weekEnd.toISOString()}),and(date_planned.lte.${weekEnd.toISOString()},date_end.gte.${weekStart.toISOString()})`)
      .not('status', 'eq', 'annule');
    if (formData.technician_id) q = q.eq('technician_id', formData.technician_id);
    if (formData.intervention_type) q = q.eq('intervention_type', formData.intervention_type);

    const [{ data: ivData }, leavesData, { data: usersData }] = await Promise.all([
      q,
      getApprovedLeaves(sd, ed),
      supabase.from('users').select('id, first_name, last_name, birth_date').not('birth_date', 'is', null).eq('is_active', true),
    ]);

    if (ivData) setCalendarInterventions(ivData as Intervention[]);
    setCalendarLeaves(leavesData || []);

    if (usersData) {
      const year = new Date().getFullYear();
      const bdays: BirthdayEntry[] = usersData
        .filter((u): u is typeof u & { birth_date: string } => typeof u.birth_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(u.birth_date))
        .map((u) => {
          const [, m, d] = u.birth_date.split('-');
          return { user_id: u.id, first_name: u.first_name || '', last_name: u.last_name || '', date: `${year}-${m}-${d}` };
        });
      setCalendarBirthdays(bdays);
    }
  }, [weekStart, weekEnd, formData.technician_id, formData.intervention_type]);

  useEffect(() => { fetchCalendarData(); }, [fetchCalendarData]);

  // Debounced client search
  useEffect(() => {
    if (!clientSearch || clientSearch.length < 2 || selectedClientId) {
      setClientSuggestions([]);
      return;
    }
    const timer = setTimeout(async () => {
      const q = clientSearch.trim();
      const digits = q.replace(/[^0-9]/g, '');
      const filters = [`last_name.ilike.%${q}%`, `first_name.ilike.%${q}%`, `company_name.ilike.%${q}%`, `address.ilike.%${q}%`];
      if (digits.length >= 3) {
        filters.push(`phone.ilike.%${digits}%`, `mobile.ilike.%${digits}%`);
      }
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data } = await (supabase as any)
        .from('clients')
        .select('id, first_name, last_name, company_name, phone, address, regie_id')
        .or(filters.join(','))
        .limit(8);
      setClientSuggestions((data as ClientOption[]) || []);
    }, 250);
    return () => clearTimeout(timer);
  }, [clientSearch, selectedClientId, supabase]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => {
      const updated = { ...prev, [name]: name === 'priority' || name === 'estimated_duration_minutes' ? parseInt(value) : value };
      // Reset technician if type changes and current tech doesn't match
      if (name === 'intervention_type' && prev.technician_id) {
        const currentTech = technicians.find(t => t.id === prev.technician_id);
        if (currentTech?.intervention_type_preference && currentTech.intervention_type_preference !== value) {
          updated.technician_id = '';
        }
      }
      return updated;
    });
  };

  const handleSlotClick = (day: Date, hour: number) => {
    if (hour >= 12 && hour < 13.5) return;
    setFormData((prev) => ({ ...prev, date_planned: format(day, 'yyyy-MM-dd'), time_planned: `${String(Math.floor(hour)).padStart(2, '0')}:${hour % 1 === 0.5 ? '30' : '00'}` }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      const isChantier = formData.intervention_type === 'chantier';
      const dates = buildInterventionDates(formData);
      const ci: Record<string, string> = {};
      if (formData.client_name) ci.name = formData.client_name;
      if (formData.client_phone) ci.phone = formData.client_phone;

      // Resolve / create client_id using the Postgres RPC
      let resolvedClientId: string | null = selectedClientId;
      if (!resolvedClientId && (formData.client_name || formData.client_phone)) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: cid, error: rpcErr } = await (supabase as any).rpc('match_or_create_client', {
          p_phone: formData.client_phone || null,
          p_name: formData.client_name || null,
          p_address: formData.address || null,
          p_email: null,
          p_regie_id: formData.regie_id || null,
          p_client_type: 'locataire',
        });
        if (!rpcErr && cid) resolvedClientId = cid as string;
      }

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data: insertedData, error } = await (supabase as any).from('interventions').insert({
        title: formData.title, description: formData.description || null, address: formData.address,
        date_planned: dates.date_planned, estimated_duration_minutes: isChantier ? 480 : formData.estimated_duration_minutes,
        status: 'planifie', priority: formData.priority,
        technician_id: formData.technician_id || null, regie_id: formData.regie_id || null,
        work_order_number: formData.work_order_number || null,
        client_info: Object.keys(ci).length > 0 ? ci : null,
        client_id: resolvedClientId,
        source_type: 'manual', intervention_type: formData.intervention_type,
        keys_info: formData.keys_info || null,
        date_end: dates.date_end,
      }).select('id');
      if (error) throw new Error(error.message);

      const newInterventionId = insertedData?.[0]?.id || null;

      // Insert cutoff reminder (works for chantier ET dépannage)
      if (cutoffEnabled && cutoffDate && newInterventionId && formData.technician_id) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: reminderErr } = await (supabase as any).from('intervention_reminders').insert({
          intervention_id: newInterventionId,
          user_id: formData.technician_id,
          reminder_date: cutoffDate,
          message: 'Avis de coupure d eau',
          reminder_type: 'cutoff',
        });
        if (!reminderErr) {
          sendPush({
            recipient_id: formData.technician_id,
            title: 'Avis de coupure d\'eau',
            message: `${formData.title} — ${formData.address}`,
            url: isChantier
              ? `/technician/chantier/${newInterventionId}`
              : `/technician/report/${newInterventionId}`,
          });
        }
      }

      // Insert notification if technician is assigned
      if (formData.technician_id) {
        const { data: { user: currentUser } } = await supabase.auth.getUser();
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await (supabase as any).from('notifications').insert({
          recipient_id: formData.technician_id,
          sender_id: currentUser?.id || null,
          title: isChantier ? 'Nouveau chantier assigné' : 'Nouvelle intervention assignée',
          message: `${formData.title} — ${formData.address}`,
          type: 'intervention_assigned',
          reference_id: newInterventionId,
          reference_type: isChantier ? 'chantier' : 'intervention',
        });
        sendPush({
          recipient_id: formData.technician_id,
          title: isChantier ? 'Nouveau chantier assigné' : 'Nouvelle intervention assignée',
          message: `${formData.title} — ${formData.address}`,
          url: isChantier ? `/technician/chantier/${newInterventionId}` : '/technician/today',
        });
      }

      toast.success('Intervention créée avec succès');
      onSuccess();
    } catch (err) {
      console.error('Error creating intervention:', err);
      toast.error(err instanceof Error ? err.message : 'Impossible d’enregistrer l’intervention.');
    } finally { setIsLoading(false); }
  };

  const getTechNameLocal = (t: Technician) => { if (t.first_name && t.last_name) return `${t.first_name} ${t.last_name}`; return t.first_name || t.last_name || t.email; };
  const selectedTechName = formData.technician_id ? getTechNameLocal(technicians.find(t => t.id === formData.technician_id)!) : 'Tous les techniciens';
  const ic = 'w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent';
  const sc = `${ic} bg-white`;

  const calendarSelectedSlot: SelectedSlot | null = isCalendarDate(formData.date_planned) && isClockTime(formData.time_planned)
    ? { date: formData.date_planned, time: formData.time_planned, durationMinutes: formData.estimated_duration_minutes || 60, title: formData.title || 'Nouvelle' }
    : null;

  return (
    <div className="flex gap-0 max-h-[85vh]">
      {/* ═══ LEFT: Formulaire ═══ */}
      <div className="w-[480px] flex-shrink-0 overflow-y-auto px-6 border-r border-gray-200">
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Titre *</label><input type="text" name="title" required value={formData.title} onChange={handleChange} className={ic} placeholder="Ex: Fuite robinet cuisine" /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Description</label><textarea name="description" rows={3} value={formData.description} onChange={handleChange} className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none" placeholder="Détails..." /></div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">Adresse *</label><input type="text" name="address" required value={formData.address} onChange={handleChange} className={ic} placeholder="Adresse complète" /></div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Technicien</label>
              <select name="technician_id" value={formData.technician_id} onChange={handleChange} className={sc}>
                <option value="">-- Non assigné --</option>
                {technicians
                  .filter(t => !formData.intervention_type || !t.intervention_type_preference || t.intervention_type_preference === formData.intervention_type)
                  .map((t) => {
                  const techLeave = formData.date_planned
                    ? calendarLeaves.find(l => l.technician_id === t.id && l.start_date <= formData.date_planned && l.end_date >= formData.date_planned)
                    : null;
                  const leaveLabel = techLeave
                    ? ` (En congé du ${format(new Date(techLeave.start_date + 'T00:00:00'), 'd MMM', { locale: fr })} au ${format(new Date(techLeave.end_date + 'T00:00:00'), 'd MMM', { locale: fr })})`
                    : '';
                  return <option key={t.id} value={t.id} disabled={!!techLeave}>{getTechNameLocal(t)}{leaveLabel}</option>;
                })}
              </select>
            </div>
            <div><label className="block text-sm font-medium text-gray-700 mb-1">Type</label><select name="intervention_type" value={formData.intervention_type} onChange={handleChange} className={sc}><option value="depannage">🔧 Dépannage</option><option value="chantier">🏗️ Chantier</option></select></div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div><label className="block text-sm font-medium text-gray-700 mb-1">Régie</label><select name="regie_id" value={formData.regie_id} onChange={handleChange} className={sc}><option value="">-- Aucune --</option>{regies.map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}</select></div>
            <div><label className="block text-sm font-medium text-gray-700 mb-1">N° Bon de travail</label><input type="text" name="work_order_number" value={formData.work_order_number} onChange={handleChange} className={ic} placeholder="Ex: #1723245" /></div>
          </div>
          <div className={`p-3 rounded-lg border ${formData.date_planned ? 'bg-green-50 border-green-200' : 'bg-amber-50 border-amber-200'}`}>
            {isCalendarDate(formData.date_planned) ? (<p className="text-sm text-green-800">📅 <strong>{format(calendarDate(formData.date_planned)!, 'EEEE d MMMM', { locale: fr })}</strong> à <strong>{formData.time_planned || '09:00'}</strong></p>) : (<p className="text-sm text-amber-800">👆 Cliquez sur un créneau libre dans le calendrier →</p>)}
          </div>
          {formData.intervention_type === 'chantier' ? (
            <div className="grid grid-cols-2 gap-3">
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Date début</label><input type="date" onInvalid={() => toast.error("Saisissez une date de début complète et valide.")} name="date_planned" value={formData.date_planned} onChange={handleChange} className={ic} /></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Date fin</label><input type="date" name="date_end" min={formData.date_planned || undefined} value={formData.date_end} onChange={handleChange} className={ic} /></div>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3">
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Date</label><input type="date" onInvalid={() => toast.error("Saisissez une date de début complète et valide.")} name="date_planned" value={formData.date_planned} onChange={handleChange} className={ic} /></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Heure</label><input type="time" name="time_planned" step="1800" value={formData.time_planned} onChange={handleChange} className={ic} /></div>
            </div>
          )}
          {formData.intervention_type === 'chantier' ? (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Priorité</label>
              <select name="priority" value={formData.priority} onChange={handleChange} className={sc}><option value={0}>Normal</option><option value={1}>Urgent</option><option value={2}>Urgence absolue</option></select>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3">
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Durée (min)</label><input type="number" name="estimated_duration_minutes" min="15" step="15" value={formData.estimated_duration_minutes} onChange={handleChange} className={ic} /></div>
              <div><label className="block text-sm font-medium text-gray-700 mb-1">Priorité</label><select name="priority" value={formData.priority} onChange={handleChange} className={sc}><option value={0}>Normal</option><option value={1}>Urgent</option><option value={2}>Urgence absolue</option></select></div>
            </div>
          )}
          {/* Avis de coupure (chantier ET dépannage) */}
          <div className="p-3 rounded-lg border border-gray-200 bg-gray-50 space-y-2">
            <label className="flex items-center gap-2.5 cursor-pointer">
              <input type="checkbox" checked={cutoffEnabled} onChange={(e) => setCutoffEnabled(e.target.checked)} className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
              <span className="flex items-center gap-1.5 text-sm font-medium text-gray-700"><Droplets className="w-4 h-4 text-blue-500" />Coupure d&apos;eau prévue</span>
            </label>
            {cutoffEnabled && (
              <div className="ml-6.5">
                <label className="block text-xs text-gray-500 mb-1">Date de la coupure</label>
                <input type="date" value={cutoffDate} onChange={(e) => setCutoffDate(e.target.value)} className={ic} />
              </div>
            )}
          </div>
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">Client</label>
            <div className="relative">
              <input
                type="text"
                value={clientSearch}
                onChange={(e) => {
                  setClientSearch(e.target.value);
                  setFormData((prev) => ({ ...prev, client_name: e.target.value }));
                  setSelectedClientId(null);
                  setShowClientDropdown(true);
                }}
                onFocus={() => setShowClientDropdown(true)}
                onBlur={() => setTimeout(() => setShowClientDropdown(false), 150)}
                className={ic}
                placeholder="Nom / téléphone / adresse — tape pour rechercher"
              />
              {showClientDropdown && clientSuggestions.length > 0 && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-10 max-h-64 overflow-y-auto">
                  {clientSuggestions.map((c) => {
                    const name = c.company_name || [c.first_name, c.last_name].filter(Boolean).join(' ');
                    return (
                      <button
                        type="button"
                        key={c.id}
                        onClick={() => {
                          setSelectedClientId(c.id);
                          setClientSearch(name);
                          setFormData((prev) => ({
                            ...prev,
                            client_name: name,
                            client_phone: c.phone || prev.client_phone,
                            address: prev.address || c.address || '',
                            regie_id: prev.regie_id || c.regie_id || '',
                          }));
                          setShowClientDropdown(false);
                        }}
                        className="w-full text-left px-3 py-2 hover:bg-blue-50 border-b border-gray-100 last:border-0"
                      >
                        <div className="font-medium text-sm text-gray-900">{name}</div>
                        <div className="text-xs text-gray-500">{c.phone || '—'} · {c.address || '—'}</div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
            {selectedClientId && (
              <div className="text-xs text-emerald-700 bg-emerald-50 border border-emerald-200 rounded-lg px-2 py-1">
                ✓ Client existant sélectionné — l&apos;intervention sera liée à sa fiche
              </div>
            )}
            <input type="tel" name="client_phone" value={formData.client_phone} onChange={handleChange} className={ic} placeholder="📞 Téléphone (optionnel si client existant)" />
          </div>
          <div><label className="block text-sm font-medium text-gray-700 mb-1">🔑 Clés & Accès</label><textarea name="keys_info" rows={2} value={formData.keys_info} onChange={handleChange} className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none" placeholder="Ex: Clés dans la boîte aux lettres, code 1234..." /></div>
          <div className="flex items-center justify-end gap-3 pt-3 border-t border-gray-100">
            <button type="button" onClick={onCancel} disabled={isLoading} className="px-4 py-2.5 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg">Annuler</button>
            <button type="submit" disabled={isLoading} className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm">{isLoading && <Loader2 className="w-4 h-4 animate-spin" />}{isLoading ? 'Création...' : "Créer l'intervention"}</button>
          </div>
        </form>
      </div>

      {/* ═══ RIGHT: TimeGridView calendrier semaine ═══ */}
      <div className="flex-1 overflow-hidden flex flex-col min-w-0">
        <div className="flex items-center justify-between mb-2 px-3 pt-3 flex-shrink-0">
          <div className="flex items-center gap-2">
            <button onClick={() => setCalendarWeek(subWeeks(calendarWeek, 1))} className="p-1.5 hover:bg-gray-100 rounded-lg"><ChevronLeft className="w-4 h-4" /></button>
            <span className="text-sm font-medium text-gray-700">{format(weekStart, 'd MMM', { locale: fr })} – {format(weekEnd, 'd MMM yyyy', { locale: fr })}</span>
            <button onClick={() => setCalendarWeek(addWeeks(calendarWeek, 1))} className="p-1.5 hover:bg-gray-100 rounded-lg"><ChevronRight className="w-4 h-4" /></button>
            <button onClick={() => setCalendarWeek(new Date())} className="px-2 py-1 text-xs text-blue-600 hover:bg-blue-50 rounded-lg font-medium">Auj.</button>
          </div>
          <span className="text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">{selectedTechName}</span>
        </div>

        <div className="flex-1 overflow-hidden mx-3 mb-3">
          <TimeGridView
            mode="week"
            currentDate={calendarWeek}
            interventions={calendarInterventions}
            leaves={calendarLeaves}
            birthdays={calendarBirthdays}
            onInterventionClick={() => {}}
            onSlotClick={handleSlotClick}
            selectedSlot={calendarSelectedSlot}
          />
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import {
  HardHat,
  Search,
  MapPin,
  AlertTriangle,
  MessageSquare,
  Loader2,
  Building2,
  Droplets,
  Zap,
  Flame,
  Plus,
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { Modal } from '@/components/ui/Modal';
import { PlanificationSplitView } from '@/components/interventions/PlanificationSplitView';
import type { PlanificationTechnician, PlanificationRegie } from '@/components/interventions/PlanificationSplitView';
import { computeChantierProgress } from '@/lib/chantier-progress';
import { format, subHours, isAfter } from 'date-fns';
import { fr } from 'date-fns/locale';

interface ChantierRow {
  id: string;
  title: string;
  address: string;
  status: string;
  date_planned: string | null;
  date_end: string | null;
  regie?: { id: string; name: string } | null;
  technician?: { id: string; first_name: string | null; last_name: string | null } | null;
}

interface CutoffNotice {
  intervention_id: string;
  end_date_estimated: string | null;
}

interface RecentMessage {
  intervention_id: string;
  created_at: string;
}

const statusConfig: Record<string, { label: string; className: string }> = {
  nouveau: { label: 'Nouveau', className: 'bg-blue-50 text-blue-700 border-blue-200' },
  planifie: { label: 'Planifié', className: 'bg-amber-50 text-amber-700 border-amber-200' },
  en_cours: { label: 'En cours', className: 'bg-orange-50 text-orange-700 border-orange-200' },
  termine: { label: 'Terminé', className: 'bg-emerald-50 text-emerald-700 border-emerald-200' },
  ready_to_bill: { label: 'Prêt à facturer', className: 'bg-amber-50 text-amber-700 border-amber-200' },
  billed: { label: 'Facturé', className: 'bg-violet-50 text-violet-700 border-violet-200' },
  annule: { label: 'Annulé', className: 'bg-gray-50 text-gray-600 border-gray-200' },
};

export default function ChantiersListPage() {
  const router = useRouter();
  const supabase = createClient();

  const [chantiers, setChantiers] = useState<ChantierRow[]>([]);
  const [activeCutoffs, setActiveCutoffs] = useState<Map<string, number>>(new Map());
  const [recentMessages, setRecentMessages] = useState<Set<string>>(new Set());
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [technicians, setTechnicians] = useState<PlanificationTechnician[]>([]);
  const [regies, setRegies] = useState<PlanificationRegie[]>([]);

  // Stats
  const [statsEnCours, setStatsEnCours] = useState(0);
  const [statsCutoffs, setStatsCutoffs] = useState(0);
  const [statsMessagesToday, setStatsMessagesToday] = useState(0);

  const fetchReferenceData = async () => {
    const { data: techData } = await supabase
      .from('users')
      .select('id, first_name, last_name, email, intervention_type_preference')
      .eq('role', 'technician')
      .order('last_name');
    if (techData) setTechnicians(techData);

    const { data: regiesData } = await supabase
      .from('regies')
      .select('id, name, email_contact')
      .eq('is_active', true)
      .order('name');
    if (regiesData) setRegies(regiesData);
  };

  const fetchChantiers = async () => {
    setIsLoading(true);
    const now = new Date().toISOString();
    const twentyFourHoursAgo = subHours(new Date(), 24).toISOString();

    // Fetch chantiers, active cutoffs, and recent messages in parallel
    const [chantiersRes, cutoffsRes, messagesRes, messagesTodayRes] = await Promise.all([
      supabase
        .from('interventions')
        .select(`
          id, title, address, status, date_planned, date_end,
          regie:regies(id, name),
          technician:users!interventions_technician_id_fkey(id, first_name, last_name)
        `)
        .eq('intervention_type', 'chantier')
        .neq('status', 'annule')
        .order('date_planned', { ascending: false }),

      // Active cutoffs (end_date > now or end_date is null and start_date < now)
      supabase
        .from('chantier_cutoff_notices')
        .select('intervention_id, end_date_estimated')
        .or(`end_date_estimated.gt.${now},end_date_estimated.is.null`),

      // Messages in last 24h
      supabase
        .from('chantier_messages')
        .select('intervention_id, created_at')
        .gte('created_at', twentyFourHoursAgo),

      // Total messages today count
      supabase
        .from('chantier_messages')
        .select('id', { count: 'exact', head: true })
        .gte('created_at', twentyFourHoursAgo),
    ]);

    if (chantiersRes.data) {
      setChantiers(chantiersRes.data as ChantierRow[]);
      setStatsEnCours(chantiersRes.data.filter((c) => c.status === 'en_cours').length);
    }

    // Build cutoff map: intervention_id → count of active cutoffs
    if (cutoffsRes.data) {
      const cutoffMap = new Map<string, number>();
      (cutoffsRes.data as CutoffNotice[]).forEach((c) => {
        cutoffMap.set(c.intervention_id, (cutoffMap.get(c.intervention_id) || 0) + 1);
      });
      setActiveCutoffs(cutoffMap);
      setStatsCutoffs(cutoffsRes.data.length);
    }

    // Build recent messages set
    if (messagesRes.data) {
      const msgSet = new Set<string>();
      (messagesRes.data as RecentMessage[]).forEach((m) => msgSet.add(m.intervention_id));
      setRecentMessages(msgSet);
    }

    setStatsMessagesToday(messagesTodayRes.count ?? 0);
    setIsLoading(false);

    // Mark chantier_update notifications as read
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await (supabase as any).from('notifications')
        .update({ is_read: true })
        .eq('recipient_id', user.id)
        .eq('type', 'chantier_update')
        .eq('is_read', false);
    }
  };

  useEffect(() => {
    fetchChantiers();
    fetchReferenceData();
  }, []);

  const handleCreateSuccess = () => {
    setIsCreateModalOpen(false);
    fetchChantiers();
  };

  const filteredChantiers = chantiers.filter((c) => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      c.title.toLowerCase().includes(q) ||
      c.address.toLowerCase().includes(q) ||
      (c.regie?.name?.toLowerCase().includes(q) ?? false) ||
      (c.technician?.first_name?.toLowerCase().includes(q) ?? false) ||
      (c.technician?.last_name?.toLowerCase().includes(q) ?? false)
    );
  });

  const getTechName = (tech: ChantierRow['technician']) => {
    if (!tech) return null;
    return [tech.first_name, tech.last_name].filter(Boolean).join(' ') || null;
  };

  // Find last message date for a chantier (we use created_at from recent messages)
  const getLastActivity = (chantier: ChantierRow) => {
    // For now, return date_planned as fallback
    return chantier.date_planned;
  };

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white rounded-xl border border-gray-200 p-4 shadow-sm">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-orange-50 flex items-center justify-center">
              <HardHat className="w-5 h-5 text-orange-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{statsEnCours}</p>
              <p className="text-sm text-gray-500">Chantiers en cours</p>
            </div>
          </div>
        </div>
        <div className="bg-white rounded-xl border border-gray-200 p-4 shadow-sm">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-red-50 flex items-center justify-center">
              <AlertTriangle className="w-5 h-5 text-red-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{statsCutoffs}</p>
              <p className="text-sm text-gray-500">Coupures actives</p>
            </div>
          </div>
        </div>
        <div className="bg-white rounded-xl border border-gray-200 p-4 shadow-sm">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-blue-50 flex items-center justify-center">
              <MessageSquare className="w-5 h-5 text-blue-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{statsMessagesToday}</p>
              <p className="text-sm text-gray-500">Messages (24h)</p>
            </div>
          </div>
        </div>
      </div>

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <p className="text-gray-500">
            {filteredChantiers.length} chantier{filteredChantiers.length !== 1 ? 's' : ''}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="relative flex-1 sm:flex-none">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Rechercher un chantier..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full sm:w-72 h-10 pl-10 pr-4 text-sm bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
          <button
            onClick={() => setIsCreateModalOpen(true)}
            className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors whitespace-nowrap"
          >
            <Plus className="w-4 h-4" />
            Nouveau chantier
          </button>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        {isLoading ? (
          <div className="p-8 text-center">
            <Loader2 className="w-8 h-8 text-blue-600 animate-spin mx-auto mb-3" />
            <p className="text-gray-500">Chargement...</p>
          </div>
        ) : filteredChantiers.length === 0 ? (
          <div className="p-12 text-center">
            <div className="w-16 h-16 rounded-xl bg-gray-100 flex items-center justify-center mx-auto mb-4">
              <HardHat className="w-8 h-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 mb-2">Aucun chantier</h3>
            <p className="text-gray-500">
              {searchQuery ? 'Aucun résultat pour cette recherche.' : 'Les chantiers planifiés apparaîtront ici.'}
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-200 bg-gray-50/50">
                  <th className="text-left py-3 px-4 font-medium text-gray-500">Titre</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-500 hidden md:table-cell">Régie</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-500 hidden lg:table-cell">Adresse</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-500 hidden sm:table-cell">Technicien</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-500">Progression</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-500">Statut</th>
                  <th className="text-left py-3 px-4 font-medium text-gray-500 hidden xl:table-cell">Dernière activité</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filteredChantiers.map((chantier) => {
                  const progress = computeChantierProgress(chantier.date_planned, chantier.date_end);
                  const status = statusConfig[chantier.status] || statusConfig.nouveau;
                  const techName = getTechName(chantier.technician);
                  const hasActiveCutoff = activeCutoffs.has(chantier.id);
                  const cutoffCount = activeCutoffs.get(chantier.id) || 0;
                  const hasRecentMessage = recentMessages.has(chantier.id);
                  const lastActivity = getLastActivity(chantier);

                  return (
                    <tr
                      key={chantier.id}
                      className="hover:bg-gray-50/50 cursor-pointer transition-colors"
                      onClick={() => router.push(`/chantiers/${chantier.id}`)}
                    >
                      {/* Title + badges */}
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-gray-900">{chantier.title}</span>
                          {hasActiveCutoff && (
                            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-semibold rounded-full bg-red-100 text-red-700" title={`${cutoffCount} coupure${cutoffCount > 1 ? 's' : ''} active${cutoffCount > 1 ? 's' : ''}`}>
                              <AlertTriangle className="w-3 h-3" />
                              {cutoffCount}
                            </span>
                          )}
                          {hasRecentMessage && (
                            <span className="inline-flex items-center gap-1 px-1.5 py-0.5 text-[10px] font-semibold rounded-full bg-orange-100 text-orange-700" title="Nouveau message">
                              <MessageSquare className="w-3 h-3" />
                            </span>
                          )}
                        </div>
                      </td>

                      {/* Régie */}
                      <td className="py-3 px-4 hidden md:table-cell">
                        {chantier.regie ? (
                          <div className="flex items-center gap-1.5 text-gray-600">
                            <Building2 className="w-3.5 h-3.5 text-gray-400" />
                            <span>{chantier.regie.name}</span>
                          </div>
                        ) : (
                          <span className="text-gray-400">—</span>
                        )}
                      </td>

                      {/* Adresse */}
                      <td className="py-3 px-4 hidden lg:table-cell">
                        <div className="flex items-center gap-1.5 text-gray-600 max-w-[200px]">
                          <MapPin className="w-3.5 h-3.5 text-gray-400 flex-shrink-0" />
                          <span className="truncate">{chantier.address}</span>
                        </div>
                      </td>

                      {/* Technicien */}
                      <td className="py-3 px-4 hidden sm:table-cell">
                        {techName ? (
                          <div className="flex items-center gap-2">
                            <div className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-700 text-xs flex items-center justify-center font-medium">
                              {techName.charAt(0)}
                            </div>
                            <span className="text-gray-700">{techName}</span>
                          </div>
                        ) : (
                          <span className="text-gray-400">Non assigné</span>
                        )}
                      </td>

                      {/* Progression */}
                      <td className="py-3 px-4">
                        <div className="flex items-center gap-2 min-w-[100px]">
                          <div className="flex-1 h-2 bg-gray-100 rounded-full overflow-hidden">
                            <div
                              className={`h-full rounded-full transition-all ${
                                progress >= 100 ? 'bg-emerald-500' : progress >= 50 ? 'bg-blue-500' : 'bg-amber-500'
                              }`}
                              style={{ width: `${progress}%` }}
                            />
                          </div>
                          <span className="text-xs font-medium text-gray-500 w-8 text-right">{progress}%</span>
                        </div>
                      </td>

                      {/* Statut */}
                      <td className="py-3 px-4">
                        <span className={`px-2.5 py-1 text-xs font-medium rounded-lg border ${status.className}`}>
                          {status.label}
                        </span>
                      </td>

                      {/* Dernière activité */}
                      <td className="py-3 px-4 text-gray-500 hidden xl:table-cell">
                        {lastActivity
                          ? format(new Date(lastActivity), 'd MMM yyyy', { locale: fr })
                          : '—'
                        }
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Modal Nouveau Chantier */}
      <Modal
        isOpen={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        title="Planifier un nouveau chantier"
        size="full"
      >
        <PlanificationSplitView
          technicians={technicians}
          regies={regies}
          onSuccess={handleCreateSuccess}
          onCancel={() => setIsCreateModalOpen(false)}
          forceInterventionType="chantier"
        />
      </Modal>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import DOMPurify from 'dompurify';
import { useSearchParams } from 'next/navigation';
import {
  Inbox,
  Mail,
  Clock,
  Building2,
  CalendarPlus,
  RefreshCw,
  AlertCircle,
  Eye,
  Archive,
  XCircle,
  FileText,
  MessageSquare,
  Paperclip,
  Image as ImageIcon,
  Download,
  Search,
  X,
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { Modal } from '@/components/ui/Modal';
import { PlanificationSplitView } from '@/components/interventions/PlanificationSplitView';
import { format, formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';

// ─── Types ────────────────────────────────────────────────────────────────────

interface EmailInbox {
  id: string;
  received_at: string;
  from_email: string;
  from_name: string | null;
  subject: string | null;
  body_text: string | null;
  body_html: string | null;
  extracted_data: {
    title?: string;
    address?: string;
    tenant_name?: string;
    tenant_phone?: string;
    description?: string;
    priority?: string;
    email_type?: string;
  } | null;
  regie_id: string | null;
  work_order_number: string | null;
  attachment_urls: string[] | null;
  status: string;
  category: string | null;
  email_type: string | null;
}

interface Regie {
  id: string;
  name: string;
  keyword: string;
  email_contact: string | null;
  email_domains: string[] | null;
}

interface Technician {
  id: string;
  first_name: string | null;
  last_name: string | null;
  email: string;
}

type StatusFilter = 'new' | 'processed' | 'ignored' | 'all';

// ─── Helper: detect email type ────────────────────────────────────────────────

function getEmailType(email: EmailInbox): 'intervention' | 'info' {
  const type = email.email_type || email.extracted_data?.email_type || 'info';
  return type === 'intervention' ? 'intervention' : 'info';
}

function isEmailUrgent(email: EmailInbox): boolean {
  return !!(email.subject?.toLowerCase().includes('urgent') || email.subject?.toLowerCase().includes('urgence') || email.extracted_data?.priority === 'urgent');
}

// ─── Main Page ────────────────────────────────────────────────────────────────

export default function InboxPage() {
  const [emails, setEmails] = useState<EmailInbox[]>([]);
  const [regies, setRegies] = useState<Regie[]>([]);
  const [technicians, setTechnicians] = useState<Technician[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('new');

  const [urgentFilterActive, setUrgentFilterActive] = useState(false);
  const [regieFilter, setRegieFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isPlanModalOpen, setIsPlanModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [selectedEmail, setSelectedEmail] = useState<EmailInbox | null>(null);

  const supabase = createClient();
  const searchParams = useSearchParams();
  const autoOpenHandled = useRef(false);

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    const { data: regiesData } = await supabase.from('regies').select('id, name, keyword, email_contact, email_domains').eq('is_active', true).order('name');
    if (regiesData) setRegies(regiesData);

    const { data: techData } = await supabase.from('users').select('id, first_name, last_name, email, intervention_type_preference').eq('role', 'technician').order('last_name');
    if (techData) setTechnicians(techData);

    // ⚠️ NE PAS charger body_html ici : c'est le plus gros champ (~86 MB sur ~1260 emails,
    // jusqu'à 9.5 MB pour un seul mail avec images inline). Il n'est utilisé que dans les
    // modales Détail / Planification — on le charge à la demande via hydrateEmailBody().
    let query = supabase.from('email_inbox').select('id, received_at, from_email, from_name, subject, body_text, extracted_data, regie_id, work_order_number, status, category, email_type, attachment_urls').order('received_at', { ascending: false });
    if (statusFilter !== 'all') query = query.eq('status', statusFilter);

    const { data: emailsData, error: emailsError } = await query;
    if (emailsError) toast.error('Erreur lors du chargement des emails');
    if (emailsData) setEmails(emailsData as EmailInbox[]);
    setIsLoading(false);
  }, [statusFilter]);

  useEffect(() => { fetchData(); }, [fetchData]);

  // Charge body_html à la demande (1 seule ligne) — il n'est pas dans la requête liste.
  // Met en cache le résultat dans la liste pour que les ré-ouvertures soient instantanées.
  const hydrateEmailBody = useCallback(async (email: EmailInbox) => {
    if (email.body_html !== undefined) return; // déjà chargé (ou inséré via realtime)
    const { data } = await supabase.from('email_inbox').select('body_html').eq('id', email.id).single();
    const html = (data as { body_html: string | null } | null)?.body_html ?? null;
    setEmails((prev) => prev.map((e) => (e.id === email.id ? { ...e, body_html: html } : e)));
    setSelectedEmail((cur) => (cur && cur.id === email.id ? { ...cur, body_html: html } : cur));
  }, [supabase]);

  useEffect(() => {
    const channel = supabase.channel('email_inbox_changes').on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'email_inbox' }, (payload) => {
      if (statusFilter === 'new' || statusFilter === 'all') {
        const newEmail = payload.new as EmailInbox;
        setEmails((prev) => [newEmail, ...prev]);
        toast.info(`Nouvel email de ${newEmail.from_name || newEmail.from_email}`);
      }
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [statusFilter]);

  // Auto-open email from URL param ?email_id=<id>
  useEffect(() => {
    const emailId = searchParams.get('email_id');
    if (emailId && emails.length > 0 && !autoOpenHandled.current) {
      const targetEmail = emails.find((e) => e.id === emailId);
      if (targetEmail) {
        autoOpenHandled.current = true;
        setSelectedEmail(targetEmail);
        setIsDetailModalOpen(true);
        void hydrateEmailBody(targetEmail);
      }
    }
  }, [searchParams, emails, hydrateEmailBody]);

  const findRegieByEmail = (fromEmail: string): string | null => {
    if (!fromEmail) return null;
    const emailDomain = fromEmail.split('@')[1]?.toLowerCase();
    if (!emailDomain) return null;
    for (const regie of regies) {
      if (regie.email_domains?.some((d) => emailDomain === d.toLowerCase())) return regie.id;
      if (regie.email_contact && fromEmail.toLowerCase() === regie.email_contact.toLowerCase()) return regie.id;
    }
    return null;
  };

  const enrichedEmails = emails.map((email) => {
    if (email.regie_id) return email;
    const matchedRegieId = findRegieByEmail(email.from_email);
    return matchedRegieId ? { ...email, regie_id: matchedRegieId } : email;
  });

  const sortByDateDesc = (a: EmailInbox, b: EmailInbox) =>
    new Date(b.received_at).getTime() - new Date(a.received_at).getTime();

  // Build a regie name lookup map for EmailCard badges and search
  const regieNameMap = new Map(regies.map((r) => [r.id, r.name]));

  const normalizedQuery = searchQuery.trim().toLowerCase();
  const filteredEmails = enrichedEmails.filter((email) => {
    if (urgentFilterActive && !isEmailUrgent(email)) return false;
    if (regieFilter && email.regie_id !== regieFilter) return false;
    if (normalizedQuery) {
      const haystack = [
        email.work_order_number,
        email.subject,
        email.from_email,
        email.from_name,
        email.body_text,
        email.extracted_data?.title,
        email.extracted_data?.address,
        email.extracted_data?.tenant_name,
        email.extracted_data?.tenant_phone,
        email.extracted_data?.description,
        email.regie_id ? regieNameMap.get(email.regie_id) : null,
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();
      if (!haystack.includes(normalizedQuery)) return false;
    }
    return true;
  });

  const chronologicalEmails = filteredEmails.sort(sortByDateDesc);

  const totalEmails = enrichedEmails.length;
  const regieEmails = enrichedEmails.filter((e) => e.regie_id).length;
  const urgentEmails = enrichedEmails.filter(isEmailUrgent).length;
  const infoEmails = enrichedEmails.filter((e) => getEmailType(e) === 'info').length;

  const handlePlanIntervention = (email: EmailInbox) => { setSelectedEmail(email); setIsPlanModalOpen(true); void hydrateEmailBody(email); };
  const handleViewDetail = (email: EmailInbox) => { setSelectedEmail(email); setIsDetailModalOpen(true); void hydrateEmailBody(email); };

  const updateEmailStatus = async (emailId: string, status: string) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error } = await (supabase as any).from('email_inbox').update({ status, processed_at: new Date().toISOString() }).eq('id', emailId);
    if (error) { toast.error('Erreur lors de la mise à jour'); return; }
    setEmails((prev) => prev.filter((e) => e.id !== emailId));
    toast.success(status === 'processed' ? 'Email marqué comme traité' : 'Email ignoré');
  };

  const promoteToIntervention = async (emailId: string) => {
    // Manual override when the AI mis-classified an intervention as "info"
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error } = await (supabase as any)
      .from('email_inbox')
      .update({ email_type: 'intervention' })
      .eq('id', emailId);
    if (error) { toast.error('Échec du reclassement'); return; }
    setEmails((prev) =>
      prev.map((e) => (e.id === emailId ? { ...e, email_type: 'intervention' } : e))
    );
    toast.success('Email marqué comme intervention');
  };

  const handleInterventionSuccess = async () => {
    if (selectedEmail) await updateEmailStatus(selectedEmail.id, 'processed');
    setIsPlanModalOpen(false);
    setSelectedEmail(null);
    fetchData();
  };

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard icon={<Mail className="w-6 h-6 text-blue-600" />} bgColor="bg-blue-50" value={totalEmails} label="Emails à traiter" />
        <StatCard icon={<Building2 className="w-6 h-6 text-amber-600" />} bgColor="bg-amber-50" value={regieEmails} label="Demandes de régies" />
        <StatCard icon={<AlertCircle className="w-6 h-6 text-red-600" />} bgColor="bg-red-50" value={urgentEmails} label="Urgents" onClick={() => setUrgentFilterActive(!urgentFilterActive)} active={urgentFilterActive} />
        <StatCard icon={<MessageSquare className="w-6 h-6 text-gray-600" />} bgColor="bg-gray-50" value={infoEmails} label="Infos / Suivi" />
      </div>

      {/* Toolbar */}
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-3">
        <div className="flex items-center gap-3 w-full lg:w-auto">
          <h2 className="text-lg font-semibold text-gray-900 whitespace-nowrap">Boîte de réception</h2>
          <div className="relative flex-1 lg:w-80">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
            <input
              type="search"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Rechercher : N° bon, sujet, expéditeur, locataire, adresse…"
              className="w-full h-10 pl-9 pr-9 text-sm bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 placeholder:text-gray-400"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery('')}
                title="Effacer la recherche"
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1 text-gray-400 hover:text-gray-700 hover:bg-gray-100 rounded transition-colors"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-3">
          <select
            value={regieFilter || ''}
            onChange={(e) => setRegieFilter(e.target.value || null)}
            className="h-10 px-3 text-sm bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="">Toutes les régies</option>
            {regies.map((r) => (
              <option key={r.id} value={r.id}>{r.name}</option>
            ))}
          </select>
          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
            {STATUS_FILTERS.map((f) => (
              <button key={f.value} onClick={() => setStatusFilter(f.value)} className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all ${statusFilter === f.value ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{f.label}</button>
            ))}
          </div>
          <button onClick={fetchData} disabled={isLoading} className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg transition-colors">
            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />Actualiser
          </button>
        </div>
      </div>

      {/* Content */}
      {isLoading ? <LoadingState /> : (
        chronologicalEmails.length === 0 ? <EmptyState statusFilter={statusFilter} /> : (
          <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
            <div className="divide-y divide-gray-100">
              {chronologicalEmails.map((email) => (
                <EmailCard
                  key={email.id}
                  email={email}
                  regieName={email.regie_id ? regieNameMap.get(email.regie_id) || null : null}
                  onPlan={() => handlePlanIntervention(email)}
                  onView={() => handleViewDetail(email)}
                  onIgnore={() => updateEmailStatus(email.id, 'ignored')}
                  onArchive={() => updateEmailStatus(email.id, 'processed')}
                  onPromote={() => promoteToIntervention(email.id)}
                  showActions={statusFilter === 'new'}
                />
              ))}
            </div>
          </div>
        )
      )}

      {/* Modal: Detail */}
      <Modal isOpen={isDetailModalOpen} onClose={() => { setIsDetailModalOpen(false); setSelectedEmail(null); }} title="Détail de l'email" size="lg">
        {selectedEmail && <EmailDetailView email={selectedEmail} regies={regies} onPlan={() => { setIsDetailModalOpen(false); handlePlanIntervention(selectedEmail); }} onIgnore={() => { updateEmailStatus(selectedEmail.id, 'ignored'); setIsDetailModalOpen(false); setSelectedEmail(null); }} onArchive={() => { updateEmailStatus(selectedEmail.id, 'processed'); setIsDetailModalOpen(false); setSelectedEmail(null); }} onPromote={() => { promoteToIntervention(selectedEmail.id); }} showActions={statusFilter === 'new'} />}
      </Modal>

      {/* Modal: Planification SPLIT VIEW — email à gauche, formulaire + calendrier à droite */}
      <Modal isOpen={isPlanModalOpen} onClose={() => { setIsPlanModalOpen(false); setSelectedEmail(null); }} title="Planifier l'intervention" size="full">
        <PlanificationSplitView email={selectedEmail} technicians={technicians} regies={regies} onSuccess={handleInterventionSuccess} onCancel={() => { setIsPlanModalOpen(false); setSelectedEmail(null); }} />
      </Modal>
    </div>
  );
}

// ─── Constants ────────────────────────────────────────────────────────────────

const STATUS_FILTERS: { value: StatusFilter; label: string }[] = [
  { value: 'new', label: 'Nouveaux' },
  { value: 'processed', label: 'Traités' },
  { value: 'ignored', label: 'Ignorés' },
  { value: 'all', label: 'Tous' },
];

// ─── Small Components ─────────────────────────────────────────────────────────

function StatCard({ icon, bgColor, value, label, onClick, active }: { icon: React.ReactNode; bgColor: string; value: number; label: string; onClick?: () => void; active?: boolean }) {
  return (
    <div onClick={onClick} className={`rounded-xl border p-5 shadow-sm transition-all ${onClick ? 'cursor-pointer hover:shadow-md' : ''} ${active ? 'bg-red-50 border-red-500 ring-1 ring-red-500' : 'bg-white border-gray-200'}`}>
      <div className="flex items-center gap-4">
        <div className={`w-12 h-12 rounded-xl ${bgColor} flex items-center justify-center`}>{icon}</div>
        <div><p className={`text-2xl font-bold ${active ? 'text-red-700' : 'text-gray-900'}`}>{value}</p><p className={`text-sm ${active ? 'text-red-600' : 'text-gray-500'}`}>{label}</p></div>
      </div>
    </div>
  );
}

function LoadingState() {
  return <div className="bg-white rounded-xl border border-gray-200 p-12 text-center"><div className="w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-3" /><p className="text-gray-500">Chargement...</p></div>;
}

function EmptyState({ statusFilter }: { statusFilter: StatusFilter }) {
  const messages: Record<StatusFilter, { title: string; desc: string }> = {
    new: { title: 'Aucune demande en attente', desc: 'Les nouveaux emails apparaîtront ici automatiquement.' },
    processed: { title: 'Aucun email traité', desc: 'Les emails traités apparaîtront ici.' },
    ignored: { title: 'Aucun email ignoré', desc: 'Les emails ignorés apparaîtront ici.' },
    all: { title: 'Aucun email', desc: 'La boîte de réception est vide.' },
  };
  const msg = messages[statusFilter];
  return (
    <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
      <div className="w-16 h-16 rounded-xl bg-gray-100 flex items-center justify-center mx-auto mb-4"><Inbox className="w-8 h-8 text-gray-400" /></div>
      <h3 className="text-lg font-semibold text-gray-900 mb-2">{msg.title}</h3>
      <p className="text-gray-500 max-w-sm mx-auto">{msg.desc}</p>
    </div>
  );
}

// ─── Email Card ──────────────────────────────────────────────────────────────

function EmailCard({ email, regieName, onPlan, onView, onIgnore, onArchive, onPromote, showActions = true }: { email: EmailInbox; regieName?: string | null; onPlan: () => void; onView: () => void; onIgnore: () => void; onArchive: () => void; onPromote?: () => void; showActions?: boolean; }) {
  const emailType = getEmailType(email);
  const isInfo = emailType === 'info';
  const isUrgent = !isInfo && isEmailUrgent(email);
  const timeAgo = formatDistanceToNow(new Date(email.received_at), { addSuffix: true, locale: fr });
  // Suspect false-negative: AI marked it "info" but a work order or regie matched
  const looksLikeIntervention = isInfo && (!!email.work_order_number || !!email.regie_id);

  return (
    <div className={`px-5 py-4 hover:bg-blue-50/40 transition-colors group cursor-pointer ${isInfo ? 'bg-gray-50/30' : ''}`} onClick={onView}>
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            {isInfo && <span className="px-2 py-0.5 text-xs font-medium bg-gray-100 text-gray-600 rounded flex-shrink-0">INFO</span>}
            {isUrgent && <span className="px-2 py-0.5 text-xs font-medium bg-red-100 text-red-700 rounded flex-shrink-0">URGENT</span>}
            {!isInfo && !isUrgent && email.regie_id && <span className="px-2 py-0.5 text-xs font-medium bg-blue-50 text-blue-600 rounded flex-shrink-0">INTERVENTION</span>}
            {email.status === 'processed' && <span className="px-2 py-0.5 text-xs font-medium bg-emerald-100 text-emerald-700 rounded flex-shrink-0">TRAITÉ</span>}
            {email.status === 'ignored' && <span className="px-2 py-0.5 text-xs font-medium bg-gray-100 text-gray-500 rounded flex-shrink-0">IGNORÉ</span>}
            {regieName && <span className="px-2 py-0.5 text-xs font-medium bg-amber-50 text-amber-700 border border-amber-200 rounded flex-shrink-0 flex items-center gap-1"><Building2 className="w-3 h-3" />{regieName}</span>}
            <h4 className={`font-medium truncate group-hover:text-blue-700 transition-colors ${isInfo ? 'text-gray-700' : 'text-gray-900'}`}>
              {email.work_order_number ? `Bon N° ${email.work_order_number}` : email.subject || 'Sans objet'}
            </h4>
            {email.work_order_number && email.subject && (
              <span className="text-xs text-gray-400 truncate hidden sm:inline-block max-w-xs">— {email.subject}</span>
            )}
          </div>
          <p className="text-sm text-gray-500 mb-1.5">De : {email.from_name || email.from_email}</p>
          {email.body_text && <p className="text-sm text-gray-400 truncate max-w-lg">{email.body_text.substring(0, 120)}...</p>}
          <div className="flex items-center gap-3 mt-2">
            <p className="text-xs text-gray-400 flex items-center gap-1"><Clock className="w-3 h-3" />{timeAgo}</p>
            {email.attachment_urls && email.attachment_urls.length > 0 && (
              <span className="text-xs text-amber-600 flex items-center gap-1"><Paperclip className="w-3 h-3" />{email.attachment_urls.length} fichier{email.attachment_urls.length > 1 ? 's' : ''}</span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0" onClick={(e) => e.stopPropagation()}>
          {showActions && (
            <>
              <button onClick={onIgnore} title="Ignorer" className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"><XCircle className="w-4 h-4" /></button>
              <button onClick={onArchive} title="Archiver" className="p-2 text-gray-400 hover:text-amber-600 hover:bg-amber-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"><Archive className="w-4 h-4" /></button>
              {looksLikeIntervention && onPromote && (
                <button
                  onClick={onPromote}
                  title="L'IA a classé cet email en 'info' mais une régie/bon a matché — convertir en intervention"
                  className="inline-flex items-center gap-1.5 px-3 py-2 text-xs font-medium text-amber-700 bg-amber-50 hover:bg-amber-100 border border-amber-200 rounded-lg transition-colors"
                >
                  Convertir en intervention
                </button>
              )}
              {!isInfo && (
                <button onClick={onPlan} className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors shadow-sm"><CalendarPlus className="w-4 h-4" />Planifier</button>
              )}
            </>
          )}
          {!showActions && <button onClick={onView} title="Voir détail" className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"><Eye className="w-4 h-4" /></button>}
        </div>
      </div>
    </div>
  );
}

// ─── Email Detail View (simplifié — montre le mail complet) ───────────────────

function EmailDetailView({ email, regies, onPlan, onIgnore, onArchive, onPromote, showActions }: { email: EmailInbox; regies: Regie[]; onPlan: () => void; onIgnore: () => void; onArchive: () => void; onPromote?: () => void; showActions: boolean; }) {
  const regie = regies.find((r) => r.id === email.regie_id);
  const emailType = getEmailType(email);
  const isInfo = emailType === 'info';
  const looksLikeIntervention = isInfo && (!!email.work_order_number || !!email.regie_id);

  return (
    <div className="space-y-5">
      {/* En-tête */}
      <div className="space-y-3">
        <div className="flex items-start justify-between gap-3">
          <div className="flex items-center gap-2">
            {isInfo ? <span className="px-2.5 py-1 text-xs font-medium bg-gray-100 text-gray-600 rounded-full flex-shrink-0">INFO</span> : <span className="px-2.5 py-1 text-xs font-medium bg-blue-50 text-blue-600 rounded-full flex-shrink-0">INTERVENTION</span>}
            <h3 className="text-lg font-semibold text-gray-900">
              {email.work_order_number ? `Bon N° ${email.work_order_number}` : email.subject || 'Sans objet'}
            </h3>
            {email.work_order_number && email.subject && (
              <span className="text-sm text-gray-500 truncate">— {email.subject}</span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 text-sm text-gray-500">
          <span className="flex items-center gap-1.5"><Mail className="w-4 h-4" />{email.from_name || email.from_email}</span>
          <span className="flex items-center gap-1.5"><Clock className="w-4 h-4" />{format(new Date(email.received_at), "d MMMM yyyy 'à' HH:mm", { locale: fr })}</span>
          {regie && <span className="flex items-center gap-1.5"><Building2 className="w-4 h-4" />{regie.name}</span>}
        </div>
      </div>

      {/* Pièces jointes */}
      {email.attachment_urls && email.attachment_urls.length > 0 && (
        <div>
          <p className="text-sm font-medium text-gray-700 mb-2">📎 Pièces jointes</p>
          <div className="space-y-3">
            {email.attachment_urls.map((url, idx) => {
              const ext = url.split('.').pop()?.split('?')[0]?.toLowerCase() || '';
              const fileName = decodeURIComponent(url.split('/').pop()?.split('?')[0] || `fichier-${idx + 1}`);
              const isPdf = ext === 'pdf';
              const isImage = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg'].includes(ext);

              if (isPdf) {
                return (
                  <div key={idx} className="border border-gray-200 rounded-lg overflow-hidden">
                    <div className="flex items-center justify-between px-3 py-2 bg-gray-50 border-b border-gray-200">
                      <span className="text-sm font-medium text-gray-700 flex items-center gap-2">
                        <FileText className="w-4 h-4 text-red-500" />
                        {fileName}
                      </span>
                      <a href={url} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-600 hover:text-blue-700 font-medium">
                        Ouvrir ↗
                      </a>
                    </div>
                    <iframe
                      src={url}
                      className="w-full h-[500px] border-0"
                      title={fileName}
                      onError={(e) => { (e.target as HTMLIFrameElement).style.display = 'none'; }}
                    />
                  </div>
                );
              }

              if (isImage) {
                return (
                  <div key={idx} className="border border-gray-200 rounded-lg overflow-hidden">
                    <div className="flex items-center justify-between px-3 py-2 bg-gray-50 border-b border-gray-200">
                      <span className="text-sm font-medium text-gray-700 flex items-center gap-2">
                        <ImageIcon className="w-4 h-4 text-blue-500" />
                        {fileName}
                      </span>
                      <a href={url} target="_blank" rel="noopener noreferrer" className="text-xs text-blue-600 hover:text-blue-700 font-medium">
                        Ouvrir ↗
                      </a>
                    </div>
                    <img
                      src={url}
                      alt={fileName}
                      className="max-w-full h-auto max-h-[500px] object-contain mx-auto p-2"
                    />
                  </div>
                );
              }

              // Document / unknown — download link
              return (
                <a
                  key={idx}
                  href={url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center gap-3 px-4 py-3 border border-gray-200 rounded-lg hover:bg-gray-50 transition-colors"
                >
                  <Download className="w-5 h-5 text-gray-400" />
                  <span className="text-sm font-medium text-gray-700 flex-1 truncate">{fileName}</span>
                  <span className="text-xs text-gray-400 uppercase flex-shrink-0">{ext || '?'}</span>
                </a>
              );
            })}
          </div>
        </div>
      )}

      {/* Contenu complet de l'email */}
      <div>
        <p className="text-sm font-medium text-gray-700 mb-2">Contenu de l&apos;email</p>
        <div className="bg-gray-50 rounded-lg p-4 max-h-96 overflow-y-auto border border-gray-200">
          {email.body_html ? (
            <div
              className="text-sm text-gray-700 prose prose-sm max-w-none"
              dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(email.body_html) }}
            />
          ) : (
            <pre className="text-sm text-gray-700 whitespace-pre-wrap font-sans leading-relaxed">
              {email.body_text || 'Aucun contenu disponible.'}
            </pre>
          )}
        </div>
      </div>

      {/* Misclassification hint */}
      {looksLikeIntervention && onPromote && (
        <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
          <div className="flex-1 text-sm">
            <p className="text-amber-900 font-medium">Cet email est classé en « info » mais une régie ou un bon de travail a été détecté.</p>
            <p className="text-amber-700 text-xs mt-0.5">Convertis-le en intervention pour activer la planification.</p>
          </div>
          <button onClick={onPromote} className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-amber-600 hover:bg-amber-700 rounded-lg shadow-sm">
            Convertir en intervention
          </button>
        </div>
      )}

      {/* Actions */}
      {showActions && (
        <div className="flex items-center justify-between pt-4 border-t border-gray-100">
          <div className="flex items-center gap-2">
            <button onClick={onIgnore} className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-red-600 bg-white border border-gray-200 hover:bg-red-50 rounded-lg transition-colors"><XCircle className="w-4 h-4" />Ignorer</button>
            <button onClick={onArchive} className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg transition-colors"><Archive className="w-4 h-4" />Archiver</button>
          </div>
          {!isInfo && (
            <button onClick={onPlan} className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors shadow-sm"><CalendarPlus className="w-4 h-4" />Planifier l&apos;intervention</button>
          )}
        </div>
      )}
    </div>
  );
}

function InfoPill({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-start gap-2.5 p-3 bg-gray-50 rounded-lg">
      <div className="text-gray-400 mt-0.5">{icon}</div>
      <div className="min-w-0"><p className="text-xs text-gray-400">{label}</p><p className="text-sm font-medium text-gray-900 truncate">{value}</p></div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
