  id: string;
  technician_id: string;
  call_received_at: string;
  intervention_started_at: string | null;
  intervention_ended_at: string | null;
  client_name: string | null;
  client_phone: string | null;
  address: string;
  problem_description: string | null;
  actions_taken: string | null;
  supplies_used: string | null;
  photos: string[];
  travel_distance_km: number | null;
  is_billable: boolean;
  status: 'draft' | 'submitted' | 'validated' | 'billed';
  intervention_id: string | null;
  technician?: Technician | null;
  created_at: string;
}

type Tab = 'planning' | 'reports' | 'history';

function getTechName(t?: Technician | null): string {
  if (!t) return '—';
  if (t.first_name && t.last_name) return `${t.first_name} ${t.last_name}`;
  return t.first_name || t.last_name || t.email;
}

export default function PiquetAdminPage() {
  const [tab, setTab] = useState<Tab>('planning');
  const [technicians, setTechnicians] = useState<Technician[]>([]);
  const [schedules, setSchedules] = useState<Schedule[]>([]);
  const [reports, setReports] = useState<PiquetReport[]>([]);
  const [historyReports, setHistoryReports] = useState<PiquetReport[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null);
  const [uploadingDocxId, setUploadingDocxId] = useState<string | null>(null);
  const docxInputsRef = useRef<Record<string, HTMLInputElement | null>>({});
  const supabase = createClient();

  const handlePiquetDocxUpload = async (reportId: string, file: File) => {
    setUploadingDocxId(reportId);
    try {
      const fd = new FormData();
      fd.append('file', file);
      const res = await fetch(`/api/piquet-report-docx?id=${reportId}`, {
        method: 'POST',
        body: fd,
      });
      const json = await res.json();
      if (!res.ok) {
        throw new Error(json.detail || json.error || 'Conversion échouée');
      }
      toast.success('Word importé et PDF mis à jour ✅');
    } catch (e) {
      console.error('Upload piquet Word error', e);
      toast.error(`Erreur upload Word: ${(e as Error).message}`);
    } finally {
      setUploadingDocxId(null);
      const input = docxInputsRef.current[reportId];
      if (input) input.value = '';
    }
  };

  const fetchAll = useCallback(async () => {
    setIsLoading(true);
    const today = new Date();
    const horizonEnd = addWeeks(today, 26);
    const [{ data: techData }, { data: schedData }, { data: reportsData }, { data: historyData }] = await Promise.all([
      supabase.from('users').select('id, first_name, last_name, email').eq('role', 'technician').eq('is_active', true).order('last_name'),
      supabase
        .from('piquet_schedule')
        .select('*, technician:users!piquet_schedule_technician_id_fkey(id, first_name, last_name, email)')
        .gte('end_date', format(today, 'yyyy-MM-dd'))
        .lte('start_date', format(horizonEnd, 'yyyy-MM-dd'))
        .order('start_date'),
      supabase
        .from('piquet_reports')
        .select('*, technician:users!piquet_reports_technician_id_fkey(id, first_name, last_name, email)')
        .in('status', ['submitted', 'draft'])
        .order('call_received_at', { ascending: false })
        .limit(50),
      supabase
        .from('piquet_reports')
        .select('*, technician:users!piquet_reports_technician_id_fkey(id, first_name, last_name, email)')
        .in('status', ['validated', 'billed'])
        .order('call_received_at', { ascending: false })
        .limit(200),
    ]);

    if (techData) setTechnicians(techData as Technician[]);
    if (schedData) setSchedules(schedData as Schedule[]);
    if (reportsData) setReports(reportsData as PiquetReport[]);
    if (historyData) setHistoryReports(historyData as PiquetReport[]);
    setIsLoading(false);
  }, [supabase]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const weeks = useMemo(() => {
    const start = startOfWeek(new Date(), { weekStartsOn: 1 });
    const end = addWeeks(start, 11); // 12 weeks ahead
    return eachWeekOfInterval({ start, end }, { weekStartsOn: 1 });
  }, []);

  const getScheduleForWeek = (weekStart: Date): Schedule | null => {
    const weekEnd = endOfWeek(weekStart, { weekStartsOn: 1 });
    return schedules.find((s) => {
      const s1 = new Date(s.start_date + 'T00:00:00');
      return isWithinInterval(s1, { start: weekStart, end: weekEnd });
    }) || null;
  };

  const handleAssignWeek = async (weekStart: Date, techId: string) => {
    const start = format(weekStart, 'yyyy-MM-dd');
    const end = format(addDays(weekStart, 6), 'yyyy-MM-dd');
    const existing = getScheduleForWeek(weekStart);
    setProcessingId(`week-${start}`);
    try {
      if (!techId) {
        // Remove assignment
        if (existing) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          const { error } = await (supabase as any).from('piquet_schedule').delete().eq('id', existing.id);
          if (error) throw new Error(error.message);
          toast.success('Semaine libérée');
        }
      } else if (existing) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error } = await (supabase as any)
          .from('piquet_schedule')
          .update({ technician_id: techId })
          .eq('id', existing.id);
        if (error) throw new Error(error.message);
        toast.success('Piquet mis à jour');
      } else {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error } = await (supabase as any).from('piquet_schedule').insert({
          technician_id: techId,
          start_date: start,
          end_date: end,
        });
        if (error) throw new Error(error.message);
        toast.success('Piquet assigné');
      }

      // Notify the assigned tech (if any)
      if (techId) {
        const startLabel = format(weekStart, 'd MMM', { locale: fr });
        const endLabel = format(addDays(weekStart, 6), 'd MMM', { locale: fr });
        const message = `Tu es de garde du ${startLabel} au ${endLabel}`;
        const { data: { user: currentUser } } = await supabase.auth.getUser();
        try {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          await (supabase as any).from('notifications').insert({
            recipient_id: techId,
            sender_id: currentUser?.id || null,
            title: 'Piquet / urgence — tu es de garde',
            message,
            type: 'piquet_assigned',
          });
        } catch {}
        sendPush({
          recipient_id: techId,
          title: 'Piquet / urgence — tu es de garde',
          message,
          url: '/technician/piquet',
        });
      }

      fetchAll();
    } catch (e) {
      console.error(e);
      toast.error('Erreur lors de la mise à jour');
    } finally {
      setProcessingId(null);
    }
  };

  const handleValidateReport = async (reportId: string) => {
    setProcessingId(reportId);
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('piquet_reports')
        .update({ status: 'validated' })
        .eq('id', reportId);
      if (error) throw new Error(error.message);
      toast.success('Rapport validé — prêt pour facturation');
      fetchAll();
    } catch (e) {
      console.error(e);
      toast.error('Erreur lors de la validation');
    } finally {
      setProcessingId(null);
    }
  };

  const handleBillReport = async (report: PiquetReport) => {
    setProcessingId(report.id);
    try {
      // Create intervention with is_piquet=true if none exists yet
      let interventionId = report.intervention_id;
      if (!interventionId) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: iv, error: ivErr } = await (supabase as any).from('interventions').insert({
          title: `Urgence nocturne — ${report.address}`,
          description: report.problem_description || null,
          address: report.address,
          date_planned: report.call_received_at,
          date_completed: report.intervention_ended_at,
          status: 'ready_to_bill',
          priority: 2,
          technician_id: report.technician_id,
          is_piquet: true,
          night_rate_multiplier: 1.5,
          source_type: 'piquet',
          client_info: report.client_name || report.client_phone ? {
            name: report.client_name || '',
            phone: report.client_phone || '',
          } : null,
        }).select('id').single();
        if (ivErr) throw new Error(ivErr.message);
        interventionId = (iv as { id: string }).id;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await (supabase as any).from('piquet_reports').update({
          status: 'billed',
          intervention_id: interventionId,
        }).eq('id', report.id);
      } else {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await (supabase as any).from('piquet_reports').update({ status: 'billed' }).eq('id', report.id);
      }
      toast.success('Intervention créée — prête à facturer');
      fetchAll();
    } catch (e) {
      console.error(e);
      toast.error('Erreur lors de la création de la facture');
    } finally {
      setProcessingId(null);
    }
  };

  const currentSchedule = useMemo(() => {
    const today = new Date();
    return schedules.find((s) => {
      const a = new Date(s.start_date + 'T00:00:00');
      const b = new Date(s.end_date + 'T23:59:59');
      return today >= a && today <= b;
    }) || null;
  }, [schedules]);

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-orange-100 flex items-center justify-center">
          <Clock className="w-5 h-5 text-orange-600" />
        </div>
        <div>
          <h1 className="text-xl font-bold text-gray-900">Service de piquet</h1>
          <p className="text-sm text-gray-500">Planning de garde + rapports d&apos;urgence nocturne</p>
        </div>
      </div>

      {currentSchedule && (
        <div className="bg-orange-50 border border-orange-200 rounded-xl p-4 flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-orange-600 flex-shrink-0 mt-0.5" />
          <div className="flex-1">
            <p className="text-sm font-semibold text-orange-900">
              Technicien de garde actuellement : {getTechName(currentSchedule.technician)}
            </p>
            <p className="text-xs text-orange-800 mt-1">
              Du {format(new Date(currentSchedule.start_date + 'T00:00:00'), 'd MMM', { locale: fr })}
              {' '}au {format(new Date(currentSchedule.end_date + 'T00:00:00'), 'd MMM yyyy', { locale: fr })}
            </p>
            <p className="text-xs text-orange-700 mt-2">
              📞 <strong>Ne pas oublier :</strong> configurer la déviation de la ligne Richoz vers son mobile.
            </p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <div className="border-b border-gray-100 flex gap-1 p-1 bg-gray-50">
          <button
            onClick={() => setTab('planning')}
            className={`flex-1 px-4 py-2 text-sm font-medium rounded-md transition-all ${tab === 'planning' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <CalendarDays className="w-4 h-4 inline-block mr-1.5" />
            Planning
          </button>
          <button
            onClick={() => setTab('reports')}
            className={`flex-1 px-4 py-2 text-sm font-medium rounded-md transition-all ${tab === 'reports' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <FileText className="w-4 h-4 inline-block mr-1.5" />
            À valider
            {reports.filter(r => r.status === 'submitted').length > 0 && (
              <span className="ml-2 px-1.5 py-0.5 text-xs bg-red-100 text-red-700 rounded-full">
                {reports.filter(r => r.status === 'submitted').length}
              </span>
            )}
          </button>
          <button
            onClick={() => setTab('history')}
            className={`flex-1 px-4 py-2 text-sm font-medium rounded-md transition-all ${tab === 'history' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
          >
            <Archive className="w-4 h-4 inline-block mr-1.5" />
            Historique
            <span className="ml-2 px-1.5 py-0.5 text-xs bg-gray-100 text-gray-600 rounded-full">
              {historyReports.length}
            </span>
          </button>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-12"><Loader2 className="w-6 h-6 text-gray-400 animate-spin" /></div>
        ) : tab === 'planning' ? (
          <div className="divide-y divide-gray-100">
            {weeks.map((weekStart) => {
              const sched = getScheduleForWeek(weekStart);
              const weekEnd = endOfWeek(weekStart, { weekStartsOn: 1 });
              const isProcessing = processingId === `week-${format(weekStart, 'yyyy-MM-dd')}`;
              return (
                <div key={weekStart.toISOString()} className="p-4 flex items-center gap-4">
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-gray-900">
                      Semaine du {format(weekStart, 'd MMM', { locale: fr })} au {format(weekEnd, 'd MMM yyyy', { locale: fr })}
                    </p>
                    {sched?.notes && <p className="text-xs text-gray-500 mt-0.5">{sched.notes}</p>}
                  </div>
                  <div className="flex items-center gap-2">
                    <select
                      value={sched?.technician_id || ''}
                      onChange={(e) => handleAssignWeek(weekStart, e.target.value)}
                      disabled={isProcessing}
                      className="h-9 px-3 text-sm bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 disabled:opacity-50"
                    >
                      <option value="">— Aucun —</option>
                      {technicians.map((t) => (
                        <option key={t.id} value={t.id}>{getTechName(t)}</option>
                      ))}
                    </select>
                    {isProcessing && <Loader2 className="w-4 h-4 text-gray-400 animate-spin" />}
                  </div>
                </div>
              );
            })}
          </div>
        ) : tab === 'history' ? (
          historyReports.length === 0 ? (
            <div className="p-12 text-center">
              <Archive className="w-12 h-12 text-gray-300 mx-auto mb-3" />
              <p className="text-gray-500">Pas encore d&apos;historique</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-100">
              {historyReports.map((r) => (
                <div key={r.id} className="p-4">
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <span className={`px-2 py-0.5 text-xs font-medium rounded-full ${
                          r.status === 'billed' ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'
                        }`}>
                          {r.status === 'billed' ? 'Facturé' : 'Validé'}
                        </span>
                        <span className="text-sm font-semibold text-gray-900">{getTechName(r.technician)}</span>
                        <span className="text-xs text-gray-500">
                          · {format(new Date(r.call_received_at), "d MMM yyyy 'à' HH:mm", { locale: fr })}
                        </span>
                      </div>
                      <div className="flex items-start gap-1 text-sm text-gray-700">
                        <MapPin className="w-3.5 h-3.5 text-gray-400 mt-0.5 flex-shrink-0" />
                        {r.address}
                      </div>
                      {r.client_name && <p className="text-sm text-gray-600 mt-0.5">👤 {r.client_name}</p>}
                      {r.problem_description && (
                        <p className="text-sm text-gray-600 mt-1 line-clamp-2">{r.problem_description}</p>
                      )}
                    </div>
                    <div className="flex flex-col items-end gap-2 flex-shrink-0">
                      <div className="flex items-center gap-2">
                        <a
                          href={`/api/piquet-report-pdf?id=${r.id}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-red-600 hover:bg-red-700 rounded-lg"
                        >
                          <Download className="w-3 h-3" /> PDF
                        </a>
                        <a
                          href={`/api/piquet-report-docx?id=${r.id}`}
                          className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg"
                        >
                          <FileType className="w-3 h-3" /> Word
                        </a>
                      </div>
                      <input
                        ref={(el) => { docxInputsRef.current[r.id] = el; }}
                        type="file"
                        accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                        className="hidden"
                        onChange={(e) => {
                          const f = e.target.files?.[0];
                          if (f) handlePiquetDocxUpload(r.id, f);
                        }}
                      />
                      <button
                        onClick={() => docxInputsRef.current[r.id]?.click()}
                        disabled={uploadingDocxId === r.id}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-blue-700 bg-white border border-blue-200 hover:bg-blue-50 rounded-lg disabled:opacity-50"
                      >
                        {uploadingDocxId === r.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <Upload className="w-3 h-3" />}
                        {uploadingDocxId === r.id ? 'Conversion…' : 'Importer Word édité'}
                      </button>
                      {r.intervention_id && (
                        <Link href={`/interventions/${r.intervention_id}`} className="text-xs text-blue-600 hover:underline">
                          Voir facture/intervention
                        </Link>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )
        ) : reports.length === 0 ? (
          <div className="p-12 text-center">
            <CheckCircle2 className="w-12 h-12 text-emerald-300 mx-auto mb-3" />
            <p className="text-gray-500">Aucun rapport d&apos;urgence en attente</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {reports.map((r) => (
              <div key={r.id} className="p-4 space-y-3">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className={`px-2 py-0.5 text-xs font-medium rounded-full ${
                        r.status === 'submitted' ? 'bg-amber-100 text-amber-700' : 'bg-gray-100 text-gray-700'
                      }`}>
                        {r.status === 'submitted' ? 'À valider' : 'Brouillon'}
                      </span>
                      <span className="text-sm font-semibold text-gray-900">
                        {getTechName(r.technician)}
                      </span>
                      <span className="text-xs text-gray-500">
                        · Appel reçu {format(new Date(r.call_received_at), "d MMM 'à' HH:mm", { locale: fr })}
                      </span>
                    </div>
                    <div className="flex items-start gap-1 text-sm text-gray-700 mb-1">
                      <MapPin className="w-3.5 h-3.5 text-gray-400 mt-0.5 flex-shrink-0" />
                      {r.address}
                    </div>
                    {r.client_name && (
                      <p className="text-sm text-gray-700">
                        👤 {r.client_name}
                        {r.client_phone && (
                          <a href={`tel:${r.client_phone}`} className="ml-2 inline-flex items-center gap-1 text-blue-600 hover:underline">
                            <Phone className="w-3 h-3" />{r.client_phone}
                          </a>
                        )}
                      </p>
                    )}
                    {r.problem_description && (
                      <p className="text-sm text-gray-600 mt-2"><strong>Problème :</strong> {r.problem_description}</p>
                    )}
                    {r.actions_taken && (
                      <p className="text-sm text-gray-600 mt-1"><strong>Actions :</strong> {r.actions_taken}</p>
                    )}
                    {r.supplies_used && (
                      <p className="text-sm text-gray-600 mt-1"><strong>Matériel :</strong> {r.supplies_used}</p>
                    )}
                    {r.photos && r.photos.length > 0 && (
                      <div className="mt-2 flex gap-2 flex-wrap">
                        {r.photos.map((url, i) => (
                          <a key={i} href={url} target="_blank" rel="noopener noreferrer">
                            <img src={url} alt="" className="w-16 h-16 rounded-lg object-cover border border-gray-200" />
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                  <div className="flex flex-col items-end gap-2 flex-shrink-0">
                    {r.status === 'submitted' && (
                      <button
                        onClick={() => handleValidateReport(r.id)}
                        disabled={processingId === r.id}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-emerald-700 bg-emerald-50 border border-emerald-200 hover:bg-emerald-100 rounded-lg disabled:opacity-50"
                      >
                        {processingId === r.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <CheckCircle2 className="w-3 h-3" />}
                        Valider
                      </button>
                    )}
                    <button
                      onClick={() => handleBillReport(r)}
                      disabled={processingId === r.id}
                      className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-orange-600 hover:bg-orange-700 rounded-lg disabled:opacity-50"
                      title="Crée une intervention is_piquet=true avec majoration ×1.5"
                    >
                      <Receipt className="w-3 h-3" />
                      Transformer en facture
                    </button>
                    <div className="flex items-center gap-2">
                      <a
                        href={`/api/piquet-report-pdf?id=${r.id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-red-600 hover:bg-red-700 rounded-lg"
                      >
                        <Download className="w-3 h-3" /> PDF
                      </a>
                      <a
                        href={`/api/piquet-report-docx?id=${r.id}`}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg"
                      >
                        <FileType className="w-3 h-3" /> Word
                      </a>
                    </div>
                    <input
                      ref={(el) => { docxInputsRef.current[r.id] = el; }}
                      type="file"
                      accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                      className="hidden"
                      onChange={(e) => {
                        const f = e.target.files?.[0];
                        if (f) handlePiquetDocxUpload(r.id, f);
                      }}
                    />
                    <button
                      onClick={() => docxInputsRef.current[r.id]?.click()}
                      disabled={uploadingDocxId === r.id}
                      className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-blue-700 bg-white border border-blue-200 hover:bg-blue-50 rounded-lg disabled:opacity-50"
                    >
                      {uploadingDocxId === r.id ? <Loader2 className="w-3 h-3 animate-spin" /> : <Upload className="w-3 h-3" />}
                      {uploadingDocxId === r.id ? 'Conversion…' : 'Importer Word édité'}
                    </button>
                    {r.intervention_id && (
                      <Link href={`/interventions/${r.intervention_id}`} className="text-xs text-blue-600 hover:underline">
                        Voir l&apos;intervention
                      </Link>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Hidden imports */}
      <UserCog className="hidden" />
      <Trash2 className="hidden" />
    </div>
  );
}

'use client';

import { technicianReportLink } from '@/lib/report-feedback';

import { useState, useEffect } from 'react';
import { createClient } from '@/lib/supabase/client';
import { formatDate, formatTime, formatCHF, cn } from '@/lib/utils';
import { REPORT_STATUS } from '@/lib/constants';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { sendPush } from '@/lib/send-push';
import {
  ClipboardCheck,
  Clock,
  CheckCircle,
  XCircle,
  FileText,
  User,
  MapPin,
  Building,
  Wrench,
  HardHat,
  BarChart3,
  MessageSquare,
  Camera,
  Image as ImageIcon,
  Loader2,
  X,
  AlertTriangle,
} from 'lucide-react';

type InterventionTypeFilter = 'all' | 'depannage' | 'chantier';

interface ReportRow {
  id: string;
  status: string;
  text_content: string | null;
  vocal_transcription: string | null;
  work_duration_minutes: number | null;
  photos: { url: string }[] | null;
  materials_used: { name: string; quantity: number; unit_price: number }[] | null;
  is_billable: boolean;
  created_at: string;
  updated_at: string;
  technician?: { id: string; first_name: string; last_name: string } | null;
  intervention?: {
    id: string;
    title: string;
    address: string;
    date_planned: string;
    status: string;
    intervention_type: string | null;
    regie?: { id: string; name: string } | null;
  } | null;
}

interface ChantierExtra {
  intervention_id: string;
  progress_percent: number;
  photo_count: number;
  last_message_at: string | null;
}

export default function ValidateReportsPage() {
  const supabase = createClient();
  const [reports, setReports] = useState<ReportRow[]>([]);
  const [chantierExtras, setChantierExtras] = useState<Map<string, ChantierExtra>>(new Map());
  const [isLoading, setIsLoading] = useState(true);
  const [typeFilter, setTypeFilter] = useState<InterventionTypeFilter>('all');
  const [rejectModalReport, setRejectModalReport] = useState<ReportRow | null>(null);
  const [rejectReason, setRejectReason] = useState('');
  const [isRejecting, setIsRejecting] = useState(false);
  const router = useRouter();

  const handleReject = async () => {
    if (!rejectModalReport || !rejectReason.trim()) {
      toast.error('Veuillez indiquer un motif de rejet');
      return;
    }
    setIsRejecting(true);
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('reports')
        .update({
          status: 'rejected',
          revision_requested: true,
          revision_message: rejectReason,
        })
        .eq('id', rejectModalReport.id).select('id').single();
      if (error) throw error;

      // Insert notification for the technician
      if (rejectModalReport.technician?.id) {
        const { data: { user: currentUser } } = await supabase.auth.getUser();
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { error: notificationError } = await (supabase as any).from('notifications').insert({
          recipient_id: rejectModalReport.technician.id,
          sender_id: currentUser?.id || null,
          title: 'Rapport rejeté',
          message: `Motif : ${rejectReason}`,
          type: 'revision_requested',
          reference_id: rejectModalReport.id,
          reference_type: 'report',
        });
        if (notificationError) throw new Error('Retour enregistré, mais notification non envoyée.');
        sendPush({
          recipient_id: rejectModalReport.technician.id,
          title: 'Rapport rejeté',
          message: `Motif : ${rejectReason}`,
          url: technicianReportLink(rejectModalReport.intervention?.id || '', rejectModalReport.id),
        });
      }

      toast.success('Rapport rejeté — technicien notifié');
      setRejectModalReport(null);
      setRejectReason('');
      router.refresh();
      // Re-fetch reports
      setReports(prev => prev.filter(r => r.id !== rejectModalReport.id));
    } catch (error) {
      console.error('Rejection error:', error);
      toast.error(error instanceof Error ? error.message : 'Impossible d’envoyer le retour.');
    } finally {
      setIsRejecting(false);
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);

      const { data: reportsData } = await supabase
        .from('reports')
        .select(`
          id, status, text_content, vocal_transcription, work_duration_minutes,
          photos, materials_used, is_billable, created_at, updated_at,
          technician:users!reports_technician_id_fkey(id, first_name, last_name),
          intervention:interventions(id, title, address, date_planned, status, intervention_type, regie:regies(id, name))
        `)
        .in('status', ['submitted', 'draft', 'rejected'])
        .order('updated_at', { ascending: false });

      if (reportsData) {
        setReports(reportsData as unknown as ReportRow[]);

        // Fetch chantier extras for chantier interventions
        const chantierInterventionIds = (reportsData as unknown as ReportRow[])
          .filter(r => r.intervention?.intervention_type === 'chantier')
          .map(r => r.intervention!.id);

        if (chantierInterventionIds.length > 0) {
          const uniqueIds = Array.from(new Set(chantierInterventionIds));
          const extras = new Map<string, ChantierExtra>();

          const [detailsRes, photosRes, messagesRes] = await Promise.all([
            supabase
              .from('chantier_details')
              .select('intervention_id, progress_percent')
              .in('intervention_id', uniqueIds),
            supabase
              .from('chantier_photos')
              .select('intervention_id')
              .in('intervention_id', uniqueIds),
            supabase
              .from('chantier_messages')
              .select('intervention_id, created_at')
              .in('intervention_id', uniqueIds)
              .order('created_at', { ascending: false }),
          ]);

          // Init all
          uniqueIds.forEach(id => {
            extras.set(id, { intervention_id: id, progress_percent: 0, photo_count: 0, last_message_at: null });
          });

          // Details
          if (detailsRes.data) {
            detailsRes.data.forEach((d: { intervention_id: string; progress_percent: number }) => {
              const e = extras.get(d.intervention_id);
              if (e) e.progress_percent = d.progress_percent;
            });
          }

          // Photo counts
          if (photosRes.data) {
            const counts = new Map<string, number>();
            photosRes.data.forEach((p: { intervention_id: string }) => {
              counts.set(p.intervention_id, (counts.get(p.intervention_id) || 0) + 1);
            });
            counts.forEach((count, id) => {
              const e = extras.get(id);
              if (e) e.photo_count = count;
            });
          }

          // Last message
          if (messagesRes.data) {
            const seen = new Set<string>();
            messagesRes.data.forEach((m: { intervention_id: string; created_at: string }) => {
              if (!seen.has(m.intervention_id)) {
                seen.add(m.intervention_id);
                const e = extras.get(m.intervention_id);
                if (e) e.last_message_at = m.created_at;
              }
            });
          }

          setChantierExtras(extras);
        }
      }

      setIsLoading(false);
    };

    fetchData();
  }, []);

  // Filter reports by intervention type
  const filteredReports = reports.filter(r => {
    if (typeFilter === 'all') return true;
    const type = r.intervention?.intervention_type;
    if (typeFilter === 'depannage') return type !== 'chantier';
    return type === 'chantier';
  });

  // Stats
  const depannageReports = reports.filter(r => r.intervention?.intervention_type !== 'chantier');
  const chantierReports = reports.filter(r => r.intervention?.intervention_type === 'chantier');
  const submittedCount = filteredReports.filter(r => r.status === 'submitted').length;
  const draftCount = filteredReports.filter(r => r.status === 'draft').length;

  return (
    <div className="space-y-6">
      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white rounded-2xl border border-gray-200/80 p-5 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-blue-50 flex items-center justify-center">
              <ClipboardCheck className="w-6 h-6 text-blue-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{submittedCount}</p>
              <p className="text-sm text-gray-500">A valider</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl border border-gray-200/80 p-5 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-amber-50 flex items-center justify-center">
              <Clock className="w-6 h-6 text-amber-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{draftCount}</p>
              <p className="text-sm text-gray-500">Brouillons</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-2xl border border-gray-200/80 p-5 shadow-sm">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-xl bg-gray-100 flex items-center justify-center">
              <FileText className="w-6 h-6 text-gray-600" />
            </div>
            <div>
              <p className="text-2xl font-bold text-gray-900">{filteredReports.length}</p>
              <p className="text-sm text-gray-500">Total en attente</p>
            </div>
          </div>
        </div>
      </div>

      {/* Type filter tabs */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setTypeFilter('all')}
          className={cn(
            'inline-flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
            typeFilter === 'all'
              ? 'bg-blue-100 text-blue-700 border border-blue-200'
              : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
          )}
        >
          <FileText className="w-4 h-4" />
          Tous
          {reports.length > 0 && (
            <span className={cn(
              'px-1.5 py-0.5 text-[10px] font-semibold rounded-full',
              typeFilter === 'all' ? 'bg-blue-200 text-blue-800' : 'bg-gray-100 text-gray-600'
            )}>
              {reports.length}
            </span>
          )}
        </button>
        <button
          onClick={() => setTypeFilter('depannage')}
          className={cn(
            'inline-flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
            typeFilter === 'depannage'
              ? 'bg-orange-100 text-orange-700 border border-orange-200'
              : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
          )}
        >
          <Wrench className="w-4 h-4" />
          Dépannage
          {depannageReports.length > 0 && (
            <span className={cn(
              'px-1.5 py-0.5 text-[10px] font-semibold rounded-full',
              typeFilter === 'depannage' ? 'bg-orange-200 text-orange-800' : 'bg-gray-100 text-gray-600'
            )}>
              {depannageReports.length}
            </span>
          )}
        </button>
        <button
          onClick={() => setTypeFilter('chantier')}
          className={cn(
            'inline-flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg transition-colors',
            typeFilter === 'chantier'
              ? 'bg-indigo-100 text-indigo-700 border border-indigo-200'
              : 'bg-white text-gray-600 border border-gray-200 hover:bg-gray-50'
          )}
        >
          <HardHat className="w-4 h-4" />
          Chantier
          {chantierReports.length > 0 && (
            <span className={cn(
              'px-1.5 py-0.5 text-[10px] font-semibold rounded-full',
              typeFilter === 'chantier' ? 'bg-indigo-200 text-indigo-800' : 'bg-gray-100 text-gray-600'
            )}>
              {chantierReports.length}
            </span>
          )}
        </button>
      </div>

      {/* Reports List */}
      <div className="bg-white rounded-2xl border border-gray-200/80 shadow-sm overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-100">
          <h2 className="font-semibold text-gray-900">Rapports à valider</h2>
          <p className="text-sm text-gray-500">
            {typeFilter === 'all'
              ? 'Tous les rapports des techniciens'
              : typeFilter === 'depannage'
                ? 'Rapports de dépannage des techniciens'
                : 'Rapports de chantier des techniciens'}
          </p>
        </div>

        {isLoading ? (
          <div className="p-12 text-center">
            <Loader2 className="w-8 h-8 text-blue-600 animate-spin mx-auto mb-3" />
            <p className="text-gray-500">Chargement...</p>
          </div>
        ) : filteredReports.length === 0 ? (
          <div className="p-12 text-center">
            <div className="w-16 h-16 rounded-2xl bg-gray-100 flex items-center justify-center mx-auto mb-4">
              <ClipboardCheck className="w-8 h-8 text-gray-400" />
            </div>
            <h3 className="text-lg font-semibold text-gray-900 mb-2">
              Aucun rapport en attente
            </h3>
            <p className="text-gray-500 max-w-sm mx-auto">
              Les rapports soumis par les techniciens apparaîtront ici pour validation.
            </p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {filteredReports.map((report) => {
              const statusKey = report.status as keyof typeof REPORT_STATUS;
              const statusInfo = REPORT_STATUS[statusKey] || REPORT_STATUS.draft;
              const intervention = report.intervention;
              const technician = report.technician;
              const photos = report.photos || [];
              const materials = report.materials_used || [];
              const totalMaterials = materials.reduce((acc, m) => acc + (m.quantity * m.unit_price), 0);

              // Chantier extras
              const isChantier = intervention?.intervention_type === 'chantier';
              const extras = isChantier && intervention ? chantierExtras.get(intervention.id) : null;

              return (
                <div key={report.id} className="p-6 hover:bg-gray-50/50 transition-colors">
                  <div className="flex items-start gap-4">
                    {/* Status indicator */}
                    <div className={cn(
                      'w-2 h-2 rounded-full mt-2 flex-shrink-0',
                      report.status === 'submitted' ? 'bg-blue-500' : 'bg-amber-500'
                    )} />

                    <div className="flex-1 min-w-0">
                      {/* Header */}
                      <div className="flex items-start justify-between gap-4 mb-3">
                        <div>
                          <h3 className="font-semibold text-gray-900">
                            {intervention?.title || 'Intervention'}
                          </h3>
                          <div className="flex flex-wrap items-center gap-3 mt-1 text-sm text-gray-500">
                            {technician && (
                              <div className="flex items-center gap-1.5">
                                <User className="w-4 h-4" />
                                <span>{technician.first_name} {technician.last_name}</span>
                              </div>
                            )}
                            {intervention?.regie && (
                              <div className="flex items-center gap-1.5">
                                <Building className="w-4 h-4" />
                                <span>{intervention.regie.name}</span>
                              </div>
                            )}
                            {intervention?.address && (
                              <div className="flex items-center gap-1.5">
                                <MapPin className="w-4 h-4" />
                                <span className="truncate max-w-[200px]">{intervention.address}</span>
                              </div>
                            )}
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          {!report.is_billable && (
                            <span className="px-3 py-1.5 rounded-lg text-xs font-bold bg-gray-200 text-gray-700 border border-gray-300">
                              NON FACTURABLE
                            </span>
                          )}
                          <span className={cn(
                            'px-2.5 py-1 rounded-lg text-xs font-medium',
                            statusInfo.color
                          )}>
                            {statusInfo.label}
                          </span>
                        </div>
                      </div>

                      {/* Chantier extra info */}
                      {isChantier && extras && (
                        <div className="flex flex-wrap items-center gap-4 text-sm text-gray-500 mb-3 p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                          <div className="flex items-center gap-1.5">
                            <BarChart3 className="w-4 h-4 text-indigo-500" />
                            <span className="text-indigo-700 font-medium">{extras.progress_percent}%</span>
                          </div>
                          <div className="flex items-center gap-1.5">
                            <Camera className="w-4 h-4 text-indigo-500" />
                            <span>{extras.photo_count} photo{extras.photo_count !== 1 ? 's' : ''}</span>
                          </div>
                          {extras.last_message_at && (
                            <div className="flex items-center gap-1.5">
                              <MessageSquare className="w-4 h-4 text-indigo-500" />
                              <span>Journal: {formatDate(extras.last_message_at, { day: 'numeric', month: 'short' })}</span>
                            </div>
                          )}
                        </div>
                      )}

                      {/* Report content preview */}
                      {(report.text_content || report.vocal_transcription) && (
                        <div className="p-3 bg-gray-50 rounded-lg mb-3">
                          <p className="text-sm text-gray-700 line-clamp-2">
                            {report.text_content || report.vocal_transcription}
                          </p>
                        </div>
                      )}

                      {/* Report metadata */}
                      <div className="flex flex-wrap items-center gap-4 text-sm text-gray-500 mb-4">
                        {report.work_duration_minutes && !isChantier && (
                          <div className="flex items-center gap-1.5">
                            <Clock className="w-4 h-4" />
                            <span>{report.work_duration_minutes} min</span>
                          </div>
                        )}
                        {photos.length > 0 && (
                          <div className="flex items-center gap-1.5">
                            <ImageIcon className="w-4 h-4" />
                            <span>{photos.length} photo{photos.length > 1 ? 's' : ''}</span>
                          </div>
                        )}
                        {materials.length > 0 && (
                          <span className="text-gray-900 font-medium">
                            Matériaux: {formatCHF(totalMaterials)}
                          </span>
                        )}
                      </div>

                      {/* Actions */}
                      <div className="flex items-center gap-2">
                        <Link
                          href={`/reports/validate/${report.id}`}
                          className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors"
                        >
                          <CheckCircle className="w-4 h-4" />
                          Voir et valider
                        </Link>
                        <button
                          onClick={() => { setRejectModalReport(report); setRejectReason(''); }}
                          className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-red-600 bg-white border border-red-200 hover:bg-red-50 rounded-lg transition-colors"
                        >
                          <XCircle className="w-4 h-4" />
                          Rejeter
                        </button>
                      </div>
                    </div>

                    {/* Date */}
                    <div className="text-right text-sm text-gray-500 flex-shrink-0">
                      <p>{formatDate(report.updated_at || report.created_at, { day: 'numeric', month: 'short' })}</p>
                      <p>{formatTime(report.updated_at || report.created_at)}</p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Reject Modal */}
      {rejectModalReport && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-red-100 rounded-full flex items-center justify-center">
                  <AlertTriangle className="w-5 h-5 text-red-600" />
                </div>
                <div>
                  <h3 className="font-semibold text-gray-900">Rejeter le rapport</h3>
                  <p className="text-sm text-gray-500">{rejectModalReport.intervention?.title || 'Intervention'}</p>
                </div>
              </div>
              <button onClick={() => setRejectModalReport(null)} className="p-1 text-gray-400 hover:text-gray-600">
                <X className="w-5 h-5" />
              </button>
            </div>
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">Motif du rejet *</label>
              <textarea
                value={rejectReason}
                onChange={(e) => setRejectReason(e.target.value)}
                placeholder="Expliquez pourquoi ce rapport est rejeté..."
                className="w-full h-32 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 resize-none"
              />
            </div>
            <div className="flex gap-3">
              <button
                onClick={() => setRejectModalReport(null)}
                className="flex-1 py-2.5 px-4 border border-gray-200 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-colors"
              >
                Annuler
              </button>
              <button
                onClick={handleReject}
                disabled={isRejecting || !rejectReason.trim()}
                className="flex-1 py-2.5 px-4 bg-red-600 text-white rounded-lg font-medium hover:bg-red-700 disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
              >
                {isRejecting ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Rejeter'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { ReactNode, useState, useEffect, useMemo } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Calendar, CalendarDays, Palmtree, LogOut, UserCircle, HardHat, Bell } from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { registerPushSubscription } from '@/lib/push-notifications';

interface TechnicianLayoutProps {
  children: ReactNode;
}

export default function TechnicianLayout({ children }: TechnicianLayoutProps) {
  const pathname = usePathname();
  const supabase = createClient();
  const [typePreference, setTypePreference] = useState<'depannage' | 'chantier' | null>(null);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    let userId: string | null = null;

    const fetchPreference = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        userId = user.id;
        const [{ data }, { count }] = await Promise.all([
          supabase.from('users').select('intervention_type_preference').eq('id', user.id).single(),
          supabase.from('notifications').select('*', { count: 'exact', head: true }).eq('recipient_id', user.id).eq('is_read', false),
        ]);
        if (data?.intervention_type_preference) {
          setTypePreference(data.intervention_type_preference as 'depannage' | 'chantier');
        }
        setUnreadCount(count || 0);
      }
    };
    fetchPreference();

    // Silently refresh SW registration if user already has a push subscription
    const pushTimer = setTimeout(async () => {
      try {
        if (!('serviceWorker' in navigator) || !('PushManager' in window)) return;
        if (Notification.permission !== 'granted') return;
        const reg = await navigator.serviceWorker.register('/sw.js');
        await navigator.serviceWorker.ready;
        const sub = await reg.pushManager.getSubscription();
        if (sub) {
          // Subscription exists — silently re-register to keep token fresh
          registerPushSubscription().catch(() => {});
        }
      } catch { /* ignore */ }
    }, 2000);

    // Poll for new notifications every 30 seconds
    const interval = setInterval(async () => {
      if (!userId) return;
      const { count } = await supabase
        .from('notifications')
        .select('*', { count: 'exact', head: true })
        .eq('recipient_id', userId)
        .eq('is_read', false);
      setUnreadCount(count || 0);
    }, 30000);

    return () => { clearInterval(interval); clearTimeout(pushTimer); };
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    window.location.href = '/login';
  };

  const navItems = useMemo(() => {
    const items = [
      {
        href: '/technician/today',
        icon: Calendar,
        label: "Aujourd'hui",
        isActive: pathname === '/technician/today',
        showFor: 'depannage' as const,
      },
      {
        href: '/technician/week',
        icon: CalendarDays,
        label: 'Semaine',
        isActive: pathname === '/technician/week',
        showFor: 'depannage' as const,
      },
      {
        href: '/technician/chantier',
        icon: HardHat,
        label: 'Chantiers',
        isActive: pathname.startsWith('/technician/chantier'),
        showFor: 'chantier' as const,
      },
      {
        href: '/technician/leave',
        icon: Palmtree,
        label: 'Congés',
        isActive: pathname === '/technician/leave',
        showFor: null as 'depannage' | 'chantier' | null,
      },
      {
        href: '/technician/profile',
        icon: UserCircle,
        label: 'Profil',
        isActive: pathname === '/technician/profile',
        showFor: null,
      },
    ];
    // Filter nav: depannage tech sees only depannage + common; chantier tech sees only chantier + common
    if (typePreference === 'depannage') {
      return items.filter(i => i.showFor === 'depannage' || i.showFor === null);
    }
    if (typePreference === 'chantier') {
      return items.filter(i => i.showFor === 'chantier' || i.showFor === null);
    }
    return items;
  }, [pathname, typePreference]);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col" style={{ paddingTop: 'env(safe-area-inset-top, 0px)' }}>
      {/* Top notification bar */}
      <div className="fixed top-0 right-0 z-50 p-3" style={{ paddingTop: 'env(safe-area-inset-top, 0px)' }}>
        <Link
          href="/technician/notifications"
          className="relative p-2.5 bg-white rounded-full shadow-md border border-gray-200 block"
        >
          <Bell className="w-5 h-5 text-gray-600" />
          {unreadCount > 0 && (
            <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">
              {unreadCount > 9 ? '9+' : unreadCount}
            </span>
          )}
        </Link>
      </div>

      {/* Main content - No sidebar, full width */}
      <main className="flex-1 overflow-y-auto" style={{ paddingBottom: 'calc(5rem + env(safe-area-inset-bottom, 0px))' }}>
        {children}
      </main>

      {/* Bottom Navigation - Style App Mobile */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 safe-area-pb">
        <div className="flex items-center justify-around h-16 max-w-lg mx-auto">
          {navItems.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={`flex flex-col items-center justify-center flex-1 py-2 transition-colors ${
                item.isActive
                  ? 'text-blue-600'
                  : 'text-gray-500 active:text-blue-600'
              }`}
            >
              <item.icon className={`w-6 h-6 ${item.isActive ? 'stroke-[2.5]' : ''}`} />
              <span className="text-xs mt-1 font-medium">{item.label}</span>
            </Link>
          ))}

          {/* Logout button */}
          <button
            onClick={handleLogout}
            className="flex flex-col items-center justify-center flex-1 py-2 text-gray-500 active:text-red-600 transition-colors"
          >
            <LogOut className="w-6 h-6" />
            <span className="text-xs mt-1 font-medium">Sortir</span>
          </button>
        </div>
      </nav>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { format, formatDistanceToNow } from 'date-fns';
import { fr } from 'date-fns/locale';
import {
  CalendarDays,
  Plus,
  Clock,
  CheckCircle,
  XCircle,
  Loader2,
  Palmtree,
  Send,
} from 'lucide-react';
import { LEAVE_TYPES, LEAVE_TYPE_ORDER, type LeaveType } from '@/lib/constants';

interface LeaveRequest {
  id: string;
  start_date: string;
  end_date: string;
  reason: string | null;
  leave_type: LeaveType;
  status: 'pending' | 'approved' | 'rejected';
  rejection_reason: string | null;
  created_at: string;
  reviewed_at: string | null;
}

const STATUS_CONFIG = {
  pending: { label: 'En attente', color: 'bg-amber-100 text-amber-700', icon: Clock },
  approved: { label: 'Accepté', color: 'bg-emerald-100 text-emerald-700', icon: CheckCircle },
  rejected: { label: 'Refusé', color: 'bg-red-100 text-red-700', icon: XCircle },
};

export default function TechnicianLeavePage() {
  const [requests, setRequests] = useState<LeaveRequest[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [userId, setUserId] = useState<string | null>(null);

  const [formData, setFormData] = useState<{
    start_date: string;
    end_date: string;
    reason: string;
    leave_type: LeaveType;
  }>({
    start_date: '',
    end_date: '',
    reason: '',
    leave_type: 'conge',
  });

  const supabase = createClient();

  // Get current user
  useEffect(() => {
    const getUser = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) setUserId(user.id);
    };
    getUser();
  }, []);

  // Fetch leave requests
  const fetchRequests = useCallback(async () => {
    if (!userId) return;
    setIsLoading(true);

    const { data, error } = await supabase
      .from('leave_requests')
      .select('*')
      .eq('technician_id', userId)
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Error fetching leave requests:', error);
    } else {
      setRequests(data as LeaveRequest[]);
    }
    setIsLoading(false);
  }, [userId]);

  useEffect(() => {
    if (userId) fetchRequests();
  }, [userId, fetchRequests]);

  // Submit new request
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId) return;

    // Validation
    if (new Date(formData.start_date) > new Date(formData.end_date)) {
      toast.error('La date de fin doit être après la date de début');
      return;
    }

    // Maladie and accident can be declared retroactively
    const allowPast = formData.leave_type === 'maladie' || formData.leave_type === 'accident';
    if (!allowPast && new Date(formData.start_date) < new Date(new Date().toDateString())) {
      toast.error('Vous ne pouvez pas demander un congé dans le passé');
      return;
    }

    setIsSubmitting(true);
    try {
      // Maladie/accident: auto-approve (déclaratif), sinon: pending
      const autoApprove = formData.leave_type === 'maladie' || formData.leave_type === 'accident';
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any)
        .from('leave_requests')
        .insert({
          technician_id: userId,
          start_date: formData.start_date,
          end_date: formData.end_date,
          reason: formData.reason || null,
          leave_type: formData.leave_type,
          status: autoApprove ? 'approved' : 'pending',
          reviewed_at: autoApprove ? new Date().toISOString() : null,
          reviewed_by: autoApprove ? userId : null,
        });

      if (error) throw new Error(error.message);

      toast.success(autoApprove ? 'Absence enregistrée' : 'Demande de congé envoyée !');
      setFormData({ start_date: '', end_date: '', reason: '', leave_type: 'conge' });
      setShowForm(false);
      fetchRequests();
    } catch (error) {
      console.error('Error submitting leave request:', error);
      toast.error('Erreur lors de l\'envoi de la demande');
    } finally {
      setIsSubmitting(false);
    }
  };

  const getDurationDays = (start: string, end: string) => {
    const diff = new Date(end).getTime() - new Date(start).getTime();
    return Math.ceil(diff / (1000 * 60 * 60 * 24)) + 1;
  };

  const pendingCount = requests.filter(r => r.status === 'pending').length;
  const approvedCount = requests.filter(r => r.status === 'approved').length;

  return (
    <div className="max-w-2xl mx-auto px-4 py-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-blue-100 flex items-center justify-center">
            <Palmtree className="w-5 h-5 text-blue-600" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-gray-900">Mes congés</h1>
            <p className="text-sm text-gray-500">
              {pendingCount > 0 ? `${pendingCount} en attente` : 'Aucune demande en attente'}
              {approvedCount > 0 ? ` · ${approvedCount} accepté${approvedCount > 1 ? 's' : ''}` : ''}
            </p>
          </div>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="inline-flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors shadow-sm"
        >
          <Plus className="w-4 h-4" />
          Demande de congé
        </button>
      </div>

      {/* Formulaire nouvelle demande */}
      {showForm && (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-5">
          <h3 className="text-sm font-semibold text-gray-900 mb-4">Nouvelle demande de congé</h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Date de début *
                </label>
                <input
                  type="date"
                  required
                  value={formData.start_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, start_date: e.target.value }))}
                  min={format(new Date(), 'yyyy-MM-dd')}
                  className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Date de fin *
                </label>
                <input
                  type="date"
                  required
                  value={formData.end_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, end_date: e.target.value }))}
                  min={formData.start_date || format(new Date(), 'yyyy-MM-dd')}
                  className="w-full h-10 px-3 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
            </div>

            {formData.start_date && formData.end_date && (
              <div className="px-3 py-2 bg-blue-50 rounded-lg text-sm text-blue-700">
                📅 {getDurationDays(formData.start_date, formData.end_date)} jour{getDurationDays(formData.start_date, formData.end_date) > 1 ? 's' : ''} d&apos;absence
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Type *</label>
              <select
                value={formData.leave_type}
                onChange={(e) => setFormData((prev) => ({ ...prev, leave_type: e.target.value as LeaveType }))}
                className="w-full h-10 px-3 text-sm bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                {LEAVE_TYPE_ORDER.map((t) => (
                  <option key={t} value={t}>{LEAVE_TYPES[t].emoji} {LEAVE_TYPES[t].label}</option>
                ))}
              </select>
              {(formData.leave_type === 'maladie' || formData.leave_type === 'accident') && (
                <p className="text-xs text-amber-700 mt-1">⚠️ Auto-validé. Pense à transmettre le certificat médical à la secrétaire.</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Motif (optionnel)
              </label>
              <textarea
                value={formData.reason}
                onChange={(e) => setFormData(prev => ({ ...prev, reason: e.target.value }))}
                placeholder="Vacances, rendez-vous médical, personnel..."
                rows={2}
                className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              />
            </div>

            <div className="flex items-center justify-end gap-3">
              <button
                type="button"
                onClick={() => setShowForm(false)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg"
              >
                Annuler
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm disabled:opacity-50"
              >
                {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                {isSubmitting ? 'Envoi...' : 'Envoyer la demande'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Liste des demandes */}
      {isLoading ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <div className="w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-3" />
          <p className="text-gray-500">Chargement...</p>
        </div>
      ) : requests.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 p-12 text-center">
          <div className="w-16 h-16 rounded-xl bg-gray-100 flex items-center justify-center mx-auto mb-4">
            <CalendarDays className="w-8 h-8 text-gray-400" />
          </div>
          <h3 className="text-lg font-semibold text-gray-900 mb-2">Aucune demande de congé</h3>
          <p className="text-gray-500 max-w-sm mx-auto">Cliquez sur &quot;Demande de congé&quot; pour en créer une.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {requests.map((req) => {
            const config = STATUS_CONFIG[req.status];
            const StatusIcon = config.icon;
            const days = getDurationDays(req.start_date, req.end_date);

            return (
              <div key={req.id} className="bg-white rounded-xl border border-gray-200 shadow-sm p-4">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                      <span className={`inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium rounded-full ${config.color}`}>
                        <StatusIcon className="w-3 h-3" />
                        {config.label}
                      </span>
                      {req.leave_type && LEAVE_TYPES[req.leave_type] && (
                        <span className={`px-2 py-0.5 text-xs font-medium rounded-full border ${LEAVE_TYPES[req.leave_type].badgeClass}`}>
                          {LEAVE_TYPES[req.leave_type].emoji} {LEAVE_TYPES[req.leave_type].label}
                        </span>
                      )}
                      <span className="text-xs text-gray-400">
                        {days} jour{days > 1 ? 's' : ''}
                      </span>
                    </div>

                    <p className="text-sm font-medium text-gray-900 mb-1">
                      {format(new Date(req.start_date + 'T00:00:00'), 'd MMMM yyyy', { locale: fr })}
                      {req.start_date !== req.end_date && (
                        <> → {format(new Date(req.end_date + 'T00:00:00'), 'd MMMM yyyy', { locale: fr })}</>
                      )}
                    </p>

                    {req.reason && (
                      <p className="text-sm text-gray-500">{req.reason}</p>
                    )}

                    {req.status === 'rejected' && req.rejection_reason && (
                      <div className="mt-2 px-3 py-2 bg-red-50 rounded-lg">
                        <p className="text-xs text-red-600">
                          <strong>Motif du refus :</strong> {req.rejection_reason}
                        </p>
                      </div>
                    )}
                  </div>

                  <span className="text-xs text-gray-400 flex-shrink-0">
                    {formatDistanceToNow(new Date(req.created_at), { addSuffix: true, locale: fr })}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

'use client';

import { reportNotificationLink } from '@/lib/report-feedback';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { ChevronLeft, Bell, Check, Loader2, Wrench, MessageSquare, HardHat, Camera } from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { formatRelativeTime } from '@/lib/utils';

interface NotificationRow {
  id: string;
  title: string;
  message: string | null;
  type: string;
  reference_id: string | null;
  reference_type: string | null;
  is_read: boolean;
  created_at: string;
  intervention_type?: string | null;
  report_intervention_id?: string | null;
}

export default function TechnicianNotificationsPage() {
  const [notifications, setNotifications] = useState<NotificationRow[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [typePreference, setTypePreference] = useState<'depannage' | 'chantier' | null>(null);
  const supabase = createClient();

  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) throw new Error('Session expirée. Reconnectez-vous pour consulter vos notifications.');

        // Fetch type preference for navigation
        const { data: prefData } = await supabase.from('users').select('intervention_type_preference').eq('id', user.id).single<{ intervention_type_preference: 'depannage' | 'chantier' | null }>();
        if (prefData?.intervention_type_preference) {
          setTypePreference(prefData.intervention_type_preference);
        }

        // Fetch notifications
        const { data, error } = await supabase
          .from('notifications')
          .select('*')
          .eq('recipient_id', user.id)
          .order('created_at', { ascending: false })
          .limit(50);

        if (error) {
          throw new Error('Impossible de charger vos notifications. Rechargez la page pour réessayer.');
        }

        if (data && data.length > 0) {
          const reportIds = data.filter((n: NotificationRow) => n.type === 'revision_requested' && n.reference_id).map((n: NotificationRow) => n.reference_id!);
          const reportMap = new Map<string, string>();
          if (reportIds.length) {
            const { data: reports, error: reportsError } = await supabase.from('reports')
              .select('id, intervention_id').eq('technician_id', user.id).in('id', reportIds);
            if (reportsError) throw new Error('Impossible de retrouver les rapports concernés. Rechargez la page pour réessayer.');
            (reports as { id: string; intervention_id: string }[] | null)?.forEach(r => reportMap.set(r.id, r.intervention_id));
          }
          // Fetch intervention types for notifications that have reference_id
          const interventionIds = data
            .filter((n: NotificationRow) => n.reference_id)
            .map((n: NotificationRow) => n.reference_id as string);

          let typeMap = new Map<string, string>();
          if (interventionIds.length > 0) {
            const uniqueIds = Array.from(new Set(interventionIds));
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const { data: ivData } = await (supabase as any)
              .from('interventions')
              .select('id, intervention_type')
              .in('id', uniqueIds);
            if (ivData) {
              typeMap = new Map(ivData.map((iv: { id: string; intervention_type: string }) => [iv.id, iv.intervention_type]));
            }
          }

          setNotifications(data.map((n: NotificationRow) => ({
            ...n,
            report_intervention_id: n.reference_id ? reportMap.get(n.reference_id) || null : null,
            intervention_type: n.reference_id ? typeMap.get(n.reference_id) || null : null,
          })) as NotificationRow[]);
        } else {
          setNotifications([]);
        }

        // Mark all as read
        await supabase
          .from('notifications')
          .update({ is_read: true })
          .eq('recipient_id', user.id)
          .eq('is_read', false);

      } catch (err) {
        setLoadError(err instanceof Error ? err.message : 'Impossible de charger vos notifications.');
      } finally {
        setIsLoading(false);
      }
    };
    fetchNotifications();
  }, []);

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-white border-b border-gray-200 px-5 py-4 flex items-center gap-3 sticky top-0 z-10">
        <Link href={typePreference === 'chantier' ? '/technician/chantier' : '/technician/today'} className="p-2 -ml-2 hover:bg-gray-100 rounded-lg">
          <ChevronLeft className="w-5 h-5 text-gray-600" />
        </Link>
        <Bell className="w-5 h-5 text-gray-600" />
        <h1 className="text-lg font-bold text-gray-900">Notifications</h1>
      </div>

      <div className="px-4 py-4">
        {isLoading ? (
          <div className="text-center py-12">
            <Loader2 className="w-8 h-8 text-blue-600 animate-spin mx-auto mb-3" />
            <p className="text-gray-500">Chargement...</p>
          </div>
        ) : loadError ? (
          <p role="alert" className="rounded-xl bg-red-50 p-4 text-red-700">{loadError}</p>
        ) : notifications.length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <Bell className="w-8 h-8 text-gray-400" />
            </div>
            <h2 className="text-lg font-semibold text-gray-900 mb-1">Aucune notification</h2>
            <p className="text-gray-500">Vous serez notifié des nouvelles interventions ici.</p>
          </div>
        ) : (
          <div className="space-y-2">
            {notifications.map((n) => (
              <Link
                key={n.id}
                href={reportNotificationLink(n)}
                className={`block bg-white rounded-2xl shadow-sm p-4 transition-all active:scale-[0.98] ${
                  !n.is_read ? 'border-l-4 border-blue-500' : 'border border-gray-100'
                }`}
              >
                <div className="flex items-start gap-3">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${
                    n.type === 'revision_requested' ? 'bg-amber-100'
                    : n.type === 'chantier_message' ? 'bg-indigo-100'
                    : n.type === 'chantier_reminder' ? 'bg-orange-100'
                    : n.type === 'intervention_assigned' ? 'bg-emerald-100'
                    : 'bg-blue-100'
                  }`}>
                    {n.type === 'revision_requested' ? (
                      <Bell className="w-5 h-5 text-amber-600" />
                    ) : n.type === 'chantier_message' ? (
                      <MessageSquare className="w-5 h-5 text-indigo-600" />
                    ) : n.type === 'chantier_reminder' ? (
                      <Bell className="w-5 h-5 text-orange-600" />
                    ) : n.type === 'intervention_assigned' ? (
                      n.intervention_type === 'chantier' ? <HardHat className="w-5 h-5 text-emerald-600" /> : <Wrench className="w-5 h-5 text-emerald-600" />
                    ) : (
                      <Check className="w-5 h-5 text-blue-600" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={`text-sm font-semibold ${!n.is_read ? 'text-gray-900' : 'text-gray-700'}`}>
                      {n.title}
                    </p>
                    {n.message && (
                      <p className={`text-sm text-gray-500 mt-0.5 ${n.type === 'revision_requested' ? 'whitespace-pre-wrap break-words' : 'line-clamp-2'}`}>{n.message}</p>
                    )}
                    <p className="text-xs text-gray-400 mt-1">{formatRelativeTime(n.created_at)}</p>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import { toast } from 'sonner';
import { format } from 'date-fns';
import { fr } from 'date-fns/locale';
import {
  Clock,
  Plus,
  Loader2,
  MapPin,
  Phone,
  Camera,
  Send,
  X,
  AlertCircle,
  Image as ImageIcon,
} from 'lucide-react';
import { normalizeImage } from '@/lib/normalize-image';
import { SignatureCanvas } from '@/components/reports/SignatureCanvas';

interface PiquetReport {
  id: string;
  call_received_at: string;
  address: string;
  client_name: string | null;
  status: string;
  created_at: string;
  problem_description: string | null;
}

interface Schedule {
  id: string;
  start_date: string;
  end_date: string;
}

export default function TechnicianPiquetPage() {
  const [userId, setUserId] = useState<string | null>(null);
  const [currentSchedule, setCurrentSchedule] = useState<Schedule | null>(null);
  const [reports, setReports] = useState<PiquetReport[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadingPhotos, setUploadingPhotos] = useState(false);
  const [form, setForm] = useState({
    call_received_at: '',
    intervention_ended_at: '',
    address: '',
    client_name: '',
    client_phone: '',
    problem_description: '',
    actions_taken: '',
    supplies_used: '',
  });
  const [photos, setPhotos] = useState<string[]>([]);
  const [signature, setSignature] = useState<string | null>(null);
  const supabase = createClient();

  useEffect(() => {
    supabase.auth.getUser().then(({ data }) => {
      if (data.user) setUserId(data.user.id);
    });
  }, [supabase]);

  const fetchData = useCallback(async () => {
    if (!userId) return;
    setIsLoading(true);
    const today = format(new Date(), 'yyyy-MM-dd');
    const [{ data: sched }, { data: reps }] = await Promise.all([
      supabase
        .from('piquet_schedule')
        .select('id, start_date, end_date')
        .eq('technician_id', userId)
        .lte('start_date', today)
        .gte('end_date', today)
        .maybeSingle(),
      supabase
        .from('piquet_reports')
        .select('id, call_received_at, address, client_name, status, created_at, problem_description')
        .eq('technician_id', userId)
        .order('created_at', { ascending: false })
        .limit(20),
    ]);

    setCurrentSchedule(sched as Schedule | null);
    if (reps) setReports(reps as PiquetReport[]);
    setIsLoading(false);
  }, [userId, supabase]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const openForm = () => {
    const now = new Date();
    // datetime-local expects YYYY-MM-DDTHH:mm local time
    const pad = (n: number) => String(n).padStart(2, '0');
    const local = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}T${pad(now.getHours())}:${pad(now.getMinutes())}`;
    setForm({
      call_received_at: local,
      intervention_ended_at: '',
      address: '',
      client_name: '',
      client_phone: '',
      problem_description: '',
      actions_taken: '',
      supplies_used: '',
    });
    setPhotos([]);
    setSignature(null);
    setShowForm(true);
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0 || !userId) return;
    setUploadingPhotos(true);
    try {
      const files = Array.from(e.target.files);
      const uploads = await Promise.all(
        files.map(async (file) => {
          const normalized = await normalizeImage(file);
          const ext = normalized.name.split('.').pop() || 'jpg';
          const path = `piquet/${userId}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
          const { error } = await supabase.storage.from('photos').upload(path, normalized, {
            contentType: normalized.type || 'image/jpeg',
            upsert: false,
          });
          if (error) throw new Error(error.message);
          const { data: urlData } = supabase.storage.from('photos').getPublicUrl(path);
          return urlData.publicUrl;
        })
      );
      setPhotos((prev) => [...prev, ...uploads]);
      toast.success(`${uploads.length} photo${uploads.length > 1 ? 's' : ''} ajoutée${uploads.length > 1 ? 's' : ''}`);
    } catch (err) {
      console.error(err);
      toast.error('Erreur lors de l\'upload');
    } finally {
      setUploadingPhotos(false);
      e.target.value = '';
    }
  };

  const removePhoto = (url: string) => {
    setPhotos((prev) => prev.filter((p) => p !== url));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId) return;
    if (!form.address) {
      toast.error('Adresse obligatoire');
      return;
    }
    setIsSubmitting(true);
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { error } = await (supabase as any).from('piquet_reports').insert({
        technician_id: userId,
        call_received_at: new Date(form.call_received_at).toISOString(),
        intervention_ended_at: form.intervention_ended_at
          ? new Date(form.intervention_ended_at).toISOString()
          : null,
        address: form.address,
        client_name: form.client_name || null,
        client_phone: form.client_phone || null,
        problem_description: form.problem_description || null,
        actions_taken: form.actions_taken || null,
        supplies_used: form.supplies_used || null,
        photos,
        client_signature: signature,
        status: 'submitted',
        is_billable: true,
      });
      if (error) throw new Error(error.message);

      // Notify secretaries (send a generic notification)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data: secretaries } = await (supabase as any)
        .from('users')
        .select('id')
        .in('role', ['secretary', 'admin'])
        .eq('is_active', true);
      if (secretaries) {
        for (const s of secretaries as { id: string }[]) {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          await (supabase as any).from('notifications').insert({
            recipient_id: s.id,
            sender_id: userId,
            title: 'Nouveau rapport de piquet',
            message: `Urgence nocturne à ${form.address}`,
            type: 'piquet_report',
          });
        }
      }

      toast.success('Rapport envoyé à la secrétaire');
      setShowForm(false);
      fetchData();
    } catch (err) {
      console.error(err);
      toast.error('Erreur lors de l\'envoi');
    } finally {
      setIsSubmitting(false);
    }
  };

  const ic = 'w-full h-12 px-3 text-base border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500';

  return (
    <div className="max-w-2xl mx-auto px-4 py-6 space-y-5">
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-orange-100 flex items-center justify-center">
          <Clock className="w-5 h-5 text-orange-600" />
        </div>
        <div>
          <h1 className="text-xl font-bold text-gray-900">Piquet / Urgence</h1>
          <p className="text-sm text-gray-500">Interventions de nuit et week-end</p>
        </div>
      </div>

      {currentSchedule ? (
        <div className="bg-orange-50 border border-orange-200 rounded-xl p-4 flex items-start gap-3">
          <AlertCircle className="w-5 h-5 text-orange-600 flex-shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-semibold text-orange-900">Tu es de garde cette semaine</p>
            <p className="text-xs text-orange-800 mt-1">
              Du {format(new Date(currentSchedule.start_date + 'T00:00:00'), 'd MMM', { locale: fr })}
              {' '}au {format(new Date(currentSchedule.end_date + 'T00:00:00'), 'd MMM yyyy', { locale: fr })}
            </p>
          </div>
        </div>
      ) : (
        <div className="bg-gray-50 border border-gray-200 rounded-xl p-4 text-sm text-gray-600">
          Tu n&apos;es pas de garde cette semaine. Tu peux quand même saisir une intervention d&apos;urgence si ça arrive.
        </div>
      )}

      {!showForm && (
        <button
          onClick={openForm}
          className="w-full flex items-center justify-center gap-2 py-5 px-6 bg-orange-600 text-white text-lg font-semibold rounded-xl hover:bg-orange-700 transition-colors shadow-sm"
        >
          <Plus className="w-5 h-5" />
          Nouvelle intervention urgence
        </button>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-gray-200 shadow-sm p-5 space-y-4">
          <div className="flex items-center justify-between mb-2">
            <h2 className="text-lg font-semibold text-gray-900">Rapport d&apos;urgence</h2>
            <button type="button" onClick={() => setShowForm(false)} className="p-1 text-gray-400 hover:text-gray-600">
              <X className="w-5 h-5" />
            </button>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Appel reçu à *</label>
            <input
              type="datetime-local"
              required
              value={form.call_received_at}
              onChange={(e) => setForm({ ...form, call_received_at: e.target.value })}
              className={ic}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Fin intervention</label>
            <input
              type="datetime-local"
              value={form.intervention_ended_at}
              onChange={(e) => setForm({ ...form, intervention_ended_at: e.target.value })}
              className={ic}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              <MapPin className="w-4 h-4 inline-block mr-1" />
              Adresse *
            </label>
            <input
              type="text"
              required
              value={form.address}
              onChange={(e) => setForm({ ...form, address: e.target.value })}
              className={ic}
              placeholder="Rue + numéro + étage"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Nom client</label>
              <input
                type="text"
                value={form.client_name}
                onChange={(e) => setForm({ ...form, client_name: e.target.value })}
                className={ic}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                <Phone className="w-4 h-4 inline-block mr-1" />
                Téléphone
              </label>
              <input
                type="tel"
                value={form.client_phone}
                onChange={(e) => setForm({ ...form, client_phone: e.target.value })}
                className={ic}
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Problème rencontré *</label>
            <textarea
              required
              rows={3}
              value={form.problem_description}
              onChange={(e) => setForm({ ...form, problem_description: e.target.value })}
              className="w-full px-3 py-2 text-base border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 resize-none"
              placeholder="Ex: Fuite d'eau sous évier, robinet bloqué..."
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Actions réalisées</label>
            <textarea
              rows={3}
              value={form.actions_taken}
              onChange={(e) => setForm({ ...form, actions_taken: e.target.value })}
              className="w-full px-3 py-2 text-base border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 resize-none"
              placeholder="Ex: Remplacement flexible, fermeture arrivée eau..."
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Matériel utilisé</label>
            <textarea
              rows={2}
              value={form.supplies_used}
              onChange={(e) => setForm({ ...form, supplies_used: e.target.value })}
              className="w-full px-3 py-2 text-base border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 resize-none"
              placeholder="1× flexible 50cm, 2× joint..."
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              <ImageIcon className="w-4 h-4 inline-block mr-1" />
              Photos
            </label>
            <div className="flex flex-wrap gap-2 mb-2">
              {photos.map((url) => (
                <div key={url} className="relative">
                  <img src={url} alt="" className="w-20 h-20 object-cover rounded-lg border border-gray-200" />
                  <button
                    type="button"
                    onClick={() => removePhoto(url)}
                    className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center text-xs"
                  >
                    ×
                  </button>
                </div>
              ))}
              <label className="w-20 h-20 border-2 border-dashed border-gray-300 rounded-lg flex items-center justify-center text-gray-400 hover:text-orange-600 hover:border-orange-400 cursor-pointer">
                {uploadingPhotos ? <Loader2 className="w-5 h-5 animate-spin" /> : <Camera className="w-5 h-5" />}
                <input
                  type="file"
                  accept="image/*"
                  multiple
                  capture="environment"
                  onChange={handlePhotoUpload}
                  disabled={uploadingPhotos}
                  className="hidden"
                />
              </label>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">✍️ Signature du client</label>
            <SignatureCanvas
              onSignatureChange={setSignature}
              existingSignature={signature}
              height={160}
            />
          </div>

          <div className="flex gap-2 pt-3 border-t border-gray-100">
            <button
              type="button"
              onClick={() => setShowForm(false)}
              disabled={isSubmitting}
              className="flex-1 py-3 text-sm font-medium text-gray-700 bg-white border border-gray-200 hover:bg-gray-50 rounded-lg"
            >
              Annuler
            </button>
            <button
              type="submit"
              disabled={isSubmitting || uploadingPhotos}
              className="flex-1 inline-flex items-center justify-center gap-2 py-3 text-sm font-medium text-white bg-orange-600 hover:bg-orange-700 rounded-lg disabled:opacity-50"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              Envoyer à la secrétaire
            </button>
          </div>
        </form>
      )}

      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <div className="p-4 border-b border-gray-100">
          <h3 className="text-sm font-semibold text-gray-900">Mes derniers rapports</h3>
        </div>
        {isLoading ? (
          <div className="flex items-center justify-center py-8"><Loader2 className="w-5 h-5 text-gray-400 animate-spin" /></div>
        ) : reports.length === 0 ? (
          <div className="p-8 text-center text-sm text-gray-400">Aucun rapport pour l&apos;instant</div>
        ) : (
          <div className="divide-y divide-gray-100">
            {reports.map((r) => (
              <div key={r.id} className="p-4">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-gray-900">{r.address}</p>
                    {r.client_name && <p className="text-xs text-gray-500 mt-0.5">👤 {r.client_name}</p>}
                    {r.problem_description && <p className="text-sm text-gray-600 mt-1 line-clamp-2">{r.problem_description}</p>}
                  </div>
                  <div className="text-right flex-shrink-0">
                    <span className={`inline-block px-2 py-0.5 text-xs font-medium rounded-full ${
                      r.status === 'billed' ? 'bg-emerald-100 text-emerald-700' :
                      r.status === 'validated' ? 'bg-blue-100 text-blue-700' :
                      'bg-amber-100 text-amber-700'
                    }`}>
                      {r.status === 'billed' ? 'Facturé' : r.status === 'validated' ? 'Validé' : 'Envoyé'}
                    </span>
                    <p className="text-xs text-gray-400 mt-1">
                      {format(new Date(r.call_received_at), "d MMM 'à' HH:mm", { locale: fr })}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { technicianReportLink } from '@/lib/report-feedback';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import {
  MapPin,
  Clock,
  ChevronRight,
  Sun,
  Coffee,
  Navigation,
  Phone,
  CheckCircle2,
  AlertCircle,
  Loader2,
  MessageSquare,
  KeyRound,
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { format, isToday, addMinutes } from 'date-fns';
import { fr } from 'date-fns/locale';

interface Intervention {
  id: string;
  title: string;
  description: string | null;
  address: string;
  date_planned: string | null;
  estimated_duration_minutes: number;
  status: string;
  priority: number;
  client_info: { name?: string; phone?: string } | null;
  intervention_type?: 'depannage' | 'chantier' | null;
  keys_info?: string | null;
}

interface RevisionReport {
  id: string;
  revision_message: string | null;
  intervention: {
    id: string;
    title: string;
    intervention_type?: string | null;
  } | null;
}

const STATUS_CONFIG: Record<string, { label: string; color: string; bgColor: string }> = {
  nouveau: { label: 'Nouveau', color: 'text-blue-700', bgColor: 'bg-blue-100' },
  planifie: { label: 'Planifié', color: 'text-amber-700', bgColor: 'bg-amber-100' },
  en_cours: { label: 'En cours', color: 'text-orange-700', bgColor: 'bg-orange-100' },
  termine: { label: 'Terminé', color: 'text-emerald-700', bgColor: 'bg-emerald-100' },
  facture: { label: 'Facturé', color: 'text-violet-700', bgColor: 'bg-violet-100' },
  annule: { label: 'Annulé', color: 'text-gray-600', bgColor: 'bg-gray-100' },
};

export default function TechnicianTodayPage() {
  const [interventions, setInterventions] = useState<Intervention[]>([]);
  const [revisionReports, setRevisionReports] = useState<RevisionReport[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [typePreference, setTypePreference] = useState<'depannage' | 'chantier' | null>(null);

  const supabase = createClient();

  // Update time every minute
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  const [userId, setUserId] = useState<string | null>(null);
  const [isOnCall, setIsOnCall] = useState<{ start_date: string; end_date: string } | null>(null);

  // Fetch user preference and id
  useEffect(() => {
    const fetchPref = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        setUserId(user.id);
        const { data } = await supabase.from('users').select('intervention_type_preference').eq('id', user.id).single<{ intervention_type_preference: 'depannage' | 'chantier' | null }>();
        if (data?.intervention_type_preference) {
          setTypePreference(data.intervention_type_preference);
        }
        // Check if on-call this week
        const today = format(new Date(), 'yyyy-MM-dd');
        const { data: sched } = await supabase
          .from('piquet_schedule')
          .select('start_date, end_date')
          .eq('technician_id', user.id)
          .lte('start_date', today)
          .gte('end_date', today)
          .maybeSingle();
        if (sched) setIsOnCall(sched as { start_date: string; end_date: string });
      }
    };
    fetchPref();
  }, []);

  // Fetch today's interventions
  const fetchInterventions = async () => {
    if (!userId) return;
    setIsLoading(true);

    const today = new Date();
    const startOfDay = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 0, 0, 0).toISOString();
    const endOfDay = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 23, 59, 59).toISOString();

    let query = supabase
      .from('interventions')
      .select('id, title, description, address, date_planned, estimated_duration_minutes, status, priority, client_info, intervention_type, keys_info')
      .eq('technician_id', userId)
      .gte('date_planned', startOfDay)
      .lte('date_planned', endOfDay)
      .neq('status', 'annule')
      .order('date_planned', { ascending: true });

    // Filter by technician type preference
    if (typePreference) {
      query = query.eq('intervention_type', typePreference);
    }

    const { data, error } = await query;

    if (!error && data) {
      setInterventions(data.map(row => {
        const info = row.client_info;
        return { ...row, client_info: info && typeof info === 'object' && !Array.isArray(info)
          ? { name: typeof info.name === 'string' ? info.name : undefined,
              phone: typeof info.phone === 'string' ? info.phone : undefined } : null };
      }));
    }

    // Fetch reports with revision requested for this technician (only rejected, not already resubmitted)
    const { data: revData } = await supabase
      .from('reports')
      .select('id, revision_message, status, intervention:interventions(id, title, intervention_type)')
      .eq('technician_id', userId)
      .eq('revision_requested', true)
      .in('status', ['rejected']);

    if (revData) {
      setRevisionReports(revData as RevisionReport[]);
    }

    setIsLoading(false);
  };

  useEffect(() => {
    if (userId) fetchInterventions();
  }, [typePreference, userId]);

  // Realtime: listen for intervention and notification changes
  useEffect(() => {
    if (!userId) return;
    const channel = supabase
      .channel('tech-today-' + userId)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'interventions', filter: 'technician_id=eq.' + userId }, () => {
        fetchInterventions();
      })
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'reports', filter: 'technician_id=eq.' + userId }, () => {
        fetchInterventions();
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [userId]);

  // Get greeting based on time
  const getGreeting = () => {
    const hour = currentTime.getHours();
    if (hour < 12) return { text: 'Bonjour', icon: Coffee };
    if (hour < 18) return { text: 'Bon après-midi', icon: Sun };
    return { text: 'Bonsoir', icon: Sun };
  };

  const greeting = getGreeting();
  const completedCount = interventions.filter(i => i.status === 'termine' || i.status === 'ready_to_bill' || i.status === 'billed').length;
  const pendingCount = interventions.filter(i => i.status !== 'termine' && i.status !== 'ready_to_bill' && i.status !== 'billed').length;

  // Open Google Maps
  const openGoogleMaps = (address: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
    window.open(url, '_blank');
  };

  // Call phone
  const callPhone = (phone: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    window.location.href = `tel:${phone}`;
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      {/* Header - Style mobile natif */}
      <div className="bg-gradient-to-br from-blue-600 to-blue-700 text-white px-5 pt-6 pb-8 rounded-b-3xl shadow-lg">
        <div className="flex items-center gap-3 mb-4">
          <greeting.icon className="w-6 h-6 text-blue-200" />
          <span className="text-blue-100 font-medium">{greeting.text}</span>
        </div>

        <h1 className="text-2xl font-bold mb-1">Mes interventions</h1>
        <p className="text-blue-100 capitalize">
          {format(currentTime, "EEEE d MMMM", { locale: fr })}
        </p>

        {/* Quick Stats */}
        <div className="flex gap-4 mt-5">
          <div className="flex-1 bg-white/20 backdrop-blur-sm rounded-2xl p-4">
            <p className="text-3xl font-bold">{pendingCount}</p>
            <p className="text-sm text-blue-100">À faire</p>
          </div>
          <div className="flex-1 bg-white/20 backdrop-blur-sm rounded-2xl p-4">
            <p className="text-3xl font-bold">{completedCount}</p>
            <p className="text-sm text-blue-100">Terminées</p>
          </div>
          <div className="flex-1 bg-white/20 backdrop-blur-sm rounded-2xl p-4">
            <p className="text-3xl font-bold">{format(currentTime, 'HH:mm')}</p>
            <p className="text-sm text-blue-100">Heure</p>
          </div>
        </div>
      </div>

      {/* Piquet banner */}
      {isOnCall && (
        <div className="px-4 -mt-4 mb-2">
          <Link
            href="/technician/piquet"
            className="block bg-gradient-to-r from-orange-500 to-red-500 text-white rounded-2xl p-4 shadow-lg active:scale-[0.98] transition-transform"
          >
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 bg-white/20 rounded-full flex items-center justify-center flex-shrink-0">
                <AlertCircle className="w-6 h-6" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-bold text-base">Tu es de garde cette semaine</p>
                <p className="text-sm text-orange-50">
                  Du {format(new Date(isOnCall.start_date + 'T00:00:00'), 'd MMM', { locale: fr })}
                  {' '}au {format(new Date(isOnCall.end_date + 'T00:00:00'), 'd MMM', { locale: fr })} — clique pour saisir une intervention nocturne
                </p>
              </div>
              <ChevronRight className="w-5 h-5 flex-shrink-0" />
            </div>
          </Link>
        </div>
      )}

      {/* Revision Alerts */}
      {revisionReports.length > 0 && (
        <div className="px-4 -mt-2 mb-2 space-y-2">
          {revisionReports.map((rev) => {
            const href = rev.intervention
              ? technicianReportLink(rev.intervention.id, rev.id)
              : '#';
            return (
            <Link
              key={rev.id}
              href={href}
              className="block bg-amber-50 border border-amber-300 rounded-2xl p-4 active:scale-[0.98] transition-all"
            >
              <div className="flex items-start gap-3">
                <div className="w-10 h-10 bg-amber-100 rounded-full flex items-center justify-center flex-shrink-0">
                  <MessageSquare className="w-5 h-5 text-amber-600" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-semibold text-amber-800 text-sm">Demande d&apos;informations</p>
                  <p className="text-sm text-amber-900 font-medium mt-0.5 truncate">
                    {rev.intervention?.title || 'Intervention'}
                  </p>
                  {rev.revision_message && (
                    <p className="text-sm text-amber-700 mt-1 line-clamp-2">{rev.revision_message}</p>
                  )}
                </div>
                <ChevronRight className="w-5 h-5 text-amber-400 flex-shrink-0 mt-2" />
              </div>
            </Link>
            );
          })}
        </div>
      )}

      {/* Content */}
      <div className="px-4 -mt-4">
        {isLoading ? (
          <div className="bg-white rounded-2xl shadow-sm p-8 text-center">
            <Loader2 className="w-8 h-8 text-blue-600 animate-spin mx-auto mb-3" />
            <p className="text-gray-500">Chargement...</p>
          </div>
        ) : interventions.length === 0 ? (
          /* Empty State */
          <div className="bg-white rounded-2xl shadow-sm p-8 text-center">
            <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <CheckCircle2 className="w-10 h-10 text-emerald-600" />
            </div>
            <h2 className="text-xl font-bold text-gray-900 mb-2">
              Aucune intervention
            </h2>
            <p className="text-gray-500 text-lg">
              Bonne journée ! ☀️
            </p>
            <p className="text-gray-400 text-sm mt-2">
              Profitez bien de votre temps libre
            </p>
          </div>
        ) : (
          /* Interventions List */
          <div className="space-y-3">
            {interventions.map((intervention, index) => {
              const status = STATUS_CONFIG[intervention.status] || STATUS_CONFIG.nouveau;
              const startTime = intervention.date_planned ? new Date(intervention.date_planned) : null;
              const endTime = startTime ? addMinutes(startTime, intervention.estimated_duration_minutes || 60) : null;
              const isCompleted = intervention.status === 'termine' || intervention.status === 'ready_to_bill' || intervention.status === 'billed';
              const isUrgent = intervention.priority > 0;

              const isChantier = intervention.intervention_type === 'chantier';
              const interventionHref = isChantier
                ? `/technician/chantier/${intervention.id}`
                : `/technician/report/${intervention.id}`;

              return (
                <Link
                  key={intervention.id}
                  href={interventionHref}
                  className={`block bg-white rounded-2xl shadow-sm overflow-hidden transition-all active:scale-[0.98] ${
                    isCompleted ? 'opacity-60' : ''
                  }`}
                >
                  {/* Urgence indicator */}
                  {isUrgent && (
                    <div className="bg-red-500 text-white text-xs font-bold px-4 py-1.5 flex items-center gap-1">
                      <AlertCircle className="w-3 h-3" />
                      {intervention.priority === 2 ? 'URGENCE ABSOLUE' : 'URGENT'}
                    </div>
                  )}

                  <div className="p-4">
                    {/* Time & Status Row */}
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-2">
                        <Clock className="w-5 h-5 text-gray-400" />
                        <span className="text-lg font-bold text-gray-900">
                          {startTime ? format(startTime, 'HH:mm') : '--:--'}
                          {endTime && (
                            <span className="text-gray-400 font-normal">
                              {' - '}{format(endTime, 'HH:mm')}
                            </span>
                          )}
                        </span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${isChantier ? 'bg-indigo-100 text-indigo-700' : 'bg-orange-100 text-orange-700'}`}>
                          {isChantier ? '🏗️ Chantier' : '🔧 Dépannage'}
                        </span>
                        <span className={`px-3 py-1 rounded-full text-sm font-semibold ${status.bgColor} ${status.color}`}>
                          {status.label}
                        </span>
                      </div>
                    </div>

                    {/* Title */}
                    <h3 className="text-lg font-semibold text-gray-900 mb-2">
                      {intervention.title}
                    </h3>

                    {/* Address with Maps link */}
                    {intervention.address && (
                      <button
                        onClick={(e) => openGoogleMaps(intervention.address, e)}
                        className="flex items-start gap-2 text-left mb-3 group"
                      >
                        <MapPin className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" />
                        <span className="text-gray-600 group-active:text-blue-600 underline-offset-2 group-active:underline">
                          {intervention.address}
                        </span>
                        <Navigation className="w-4 h-4 text-blue-500 flex-shrink-0 mt-0.5" />
                      </button>
                    )}

                    {/* Keys/access info */}
                    {intervention.keys_info && (
                      <div className="flex items-center gap-2 mb-3 px-3 py-2 bg-amber-50 border border-amber-200 rounded-lg">
                        <KeyRound className="w-4 h-4 text-amber-600 flex-shrink-0" />
                        <span className="text-sm font-medium text-amber-800">{intervention.keys_info}</span>
                      </div>
                    )}

                    {/* Client info */}
                    {intervention.client_info?.name && (
                      <div className="flex items-center justify-between pt-3 border-t border-gray-100">
                        <div className="flex items-center gap-2 text-gray-600">
                          <span className="font-medium">{intervention.client_info.name}</span>
                        </div>
                        {intervention.client_info?.phone && (
                          <button
                            onClick={(e) => callPhone(intervention.client_info!.phone!, e)}
                            className="flex items-center gap-2 px-3 py-1.5 bg-emerald-100 text-emerald-700 rounded-full text-sm font-medium active:bg-emerald-200"
                          >
                            <Phone className="w-4 h-4" />
                            Appeler
                          </button>
                        )}
                      </div>
                    )}

                    {/* Arrow indicator */}
                    <div className="flex items-center justify-end mt-3 pt-3 border-t border-gray-100">
                      <span className="text-sm text-blue-600 font-medium flex items-center gap-1">
                        {isChantier ? 'Voir le chantier' : isCompleted ? 'Voir le rapport' : 'Faire le rapport'}
                        <ChevronRight className="w-4 h-4" />
                      </span>
                    </div>
                  </div>
                </Link>
              );
            })}
          </div>
        )}

        {/* Refresh hint */}
        {!isLoading && interventions.length > 0 && (
          <p className="text-center text-gray-400 text-sm mt-6">
            Tirez vers le bas pour actualiser
          </p>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import {
  ChevronLeft,
  ChevronRight,
  MapPin,
  Clock,
  ChevronDown,
  Loader2,
  Calendar,
  MessageSquare,
  KeyRound,
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { 
  format, 
  startOfWeek, 
  endOfWeek, 
  addWeeks, 
  addDays, 
  isToday, 
  isSameDay,
  addMinutes
} from 'date-fns';
import { fr } from 'date-fns/locale';

interface Intervention {
  id: string;
  title: string;
  address: string;
  date_planned: string | null;
  estimated_duration_minutes: number;
  status: string;
  intervention_type?: 'depannage' | 'chantier' | null;
  keys_info?: string | null;
}

interface RevisionReport {
  id: string;
  revision_message: string | null;
  intervention: {
    id: string;
    title: string;
    intervention_type?: string | null;
  } | null;
}

const STATUS_COLORS: Record<string, string> = {
  nouveau: 'bg-blue-500',
  planifie: 'bg-amber-500',
  en_cours: 'bg-orange-500',
  termine: 'bg-emerald-500',
  facture: 'bg-violet-500',
  annule: 'bg-gray-400',
};

export default function TechnicianWeekPage() {
  const [currentWeekStart, setCurrentWeekStart] = useState(() =>
    startOfWeek(new Date(), { weekStartsOn: 1 })
  );
  const [interventions, setInterventions] = useState<Intervention[]>([]);
  const [revisionReports, setRevisionReports] = useState<RevisionReport[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [expandedDay, setExpandedDay] = useState<string | null>(null);
  const [typePreference, setTypePreference] = useState<'depannage' | 'chantier' | null>(null);

  const [userId, setUserId] = useState<string | null>(null);
  const supabase = createClient();

  const weekEnd = endOfWeek(currentWeekStart, { weekStartsOn: 1 });
  const days = Array.from({ length: 7 }, (_, i) => addDays(currentWeekStart, i));

  // Fetch user preference and id
  useEffect(() => {
    const fetchPref = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        setUserId(user.id);
        const { data } = await supabase.from('users').select('intervention_type_preference').eq('id', user.id).single();
        if (data?.intervention_type_preference) {
          setTypePreference(data.intervention_type_preference as 'depannage' | 'chantier');
        }
      }
    };
    fetchPref();
  }, []);

  // Fetch week's interventions
  const fetchInterventions = async () => {
    if (!userId) return;
    setIsLoading(true);

    let query = supabase
      .from('interventions')
      .select('id, title, address, date_planned, estimated_duration_minutes, status, intervention_type, keys_info')
      .eq('technician_id', userId)
      .gte('date_planned', currentWeekStart.toISOString())
      .lte('date_planned', weekEnd.toISOString())
      .neq('status', 'annule')
      .order('date_planned', { ascending: true });

    // Filter by technician type preference
    if (typePreference) {
      query = query.eq('intervention_type', typePreference);
    }

    const { data, error } = await query;

    if (!error && data) {
      setInterventions(data);
    }

    // Fetch reports with revision requested (only rejected, not yet resubmitted)
    const { data: revData } = await supabase
      .from('reports')
      .select('id, revision_message, status, intervention:interventions(id, title, intervention_type)')
      .eq('technician_id', userId)
      .eq('revision_requested', true)
      .in('status', ['rejected']);

    if (revData) {
      setRevisionReports(revData as RevisionReport[]);
    }

    setIsLoading(false);
  };

  useEffect(() => {
    if (userId) fetchInterventions();
  }, [currentWeekStart, typePreference, userId]);

  // Group interventions by day
  const getInterventionsForDay = (day: Date) => {
    return interventions.filter(intervention => {
      if (!intervention.date_planned) return false;
      return isSameDay(new Date(intervention.date_planned), day);
    });
  };

  const navigateWeek = (direction: number) => {
    setCurrentWeekStart(prev => addWeeks(prev, direction));
    setExpandedDay(null);
  };

  const goToThisWeek = () => {
    setCurrentWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }));
    setExpandedDay(null);
  };

  const isCurrentWeek = isSameDay(
    currentWeekStart,
    startOfWeek(new Date(), { weekStartsOn: 1 })
  );

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      {/* Header */}
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-700 text-white px-5 pt-6 pb-6 rounded-b-3xl shadow-lg">
        <div className="flex items-center gap-3 mb-4">
          <Calendar className="w-6 h-6 text-indigo-200" />
          <span className="text-indigo-100 font-medium">Vue semaine</span>
        </div>

        <h1 className="text-2xl font-bold mb-1">Ma semaine</h1>
        <p className="text-indigo-100">
          {format(currentWeekStart, 'd MMM', { locale: fr })} - {format(weekEnd, 'd MMM yyyy', { locale: fr })}
        </p>

        {/* Week Navigation */}
        <div className="flex items-center justify-between mt-5">
          <button
            onClick={() => navigateWeek(-1)}
            className="p-2 bg-white/20 rounded-xl active:bg-white/30 transition-colors"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>

          {!isCurrentWeek && (
            <button
              onClick={goToThisWeek}
              className="px-4 py-2 bg-white/20 rounded-xl text-sm font-medium active:bg-white/30"
            >
              Cette semaine
            </button>
          )}

          <button
            onClick={() => navigateWeek(1)}
            className="p-2 bg-white/20 rounded-xl active:bg-white/30 transition-colors"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Revision Alerts */}
      {revisionReports.length > 0 && (
        <div className="px-4 -mt-2 mb-2 space-y-2">
          {revisionReports.map((rev) => {
            const isChantier = rev.intervention?.intervention_type === 'chantier';
            const href = rev.intervention
              ? (isChantier ? `/technician/chantier/${rev.intervention.id}` : `/technician/report/${rev.intervention.id}`)
              : '#';
            return (
              <Link
                key={rev.id}
                href={href}
                className="block bg-amber-50 border border-amber-300 rounded-2xl p-4 active:scale-[0.98] transition-all"
              >
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-amber-100 rounded-full flex items-center justify-center flex-shrink-0">
                    <MessageSquare className="w-5 h-5 text-amber-600" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-semibold text-amber-800 text-sm">Demande d&apos;informations</p>
                    <p className="text-sm text-amber-900 font-medium mt-0.5 truncate">
                      {rev.intervention?.title || 'Intervention'}
                    </p>
                    {rev.revision_message && (
                      <p className="text-sm text-amber-700 mt-1 line-clamp-2">{rev.revision_message}</p>
                    )}
                  </div>
                  <ChevronRight className="w-5 h-5 text-amber-400 flex-shrink-0 mt-2" />
                </div>
              </Link>
            );
          })}
        </div>
      )}

      {/* Content */}
      <div className="px-4 -mt-4">
        {isLoading ? (
          <div className="bg-white rounded-2xl shadow-sm p-8 text-center">
            <Loader2 className="w-8 h-8 text-indigo-600 animate-spin mx-auto mb-3" />
            <p className="text-gray-500">Chargement...</p>
          </div>
        ) : (
          <div className="space-y-2">
            {days.map((day) => {
              const dayInterventions = getInterventionsForDay(day);
              const dayKey = format(day, 'yyyy-MM-dd');
              const isExpanded = expandedDay === dayKey;
              const dayIsToday = isToday(day);
              const hasInterventions = dayInterventions.length > 0;

              return (
                <div key={dayKey} className="bg-white rounded-2xl shadow-sm overflow-hidden">
                  {/* Day Header */}
                  <button
                    onClick={() => setExpandedDay(isExpanded ? null : dayKey)}
                    className={`w-full flex items-center justify-between p-4 transition-colors ${
                      dayIsToday ? 'bg-blue-50' : ''
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      {/* Day number circle */}
                      <div
                        className={`w-10 h-10 rounded-full flex items-center justify-center text-lg font-bold ${
                          dayIsToday
                            ? 'bg-blue-600 text-white'
                            : hasInterventions
                            ? 'bg-gray-100 text-gray-900'
                            : 'bg-gray-50 text-gray-400'
                        }`}
                      >
                        {format(day, 'd')}
                      </div>
                      <div className="text-left">
                        <p className={`font-semibold capitalize ${dayIsToday ? 'text-blue-600' : 'text-gray-900'}`}>
                          {format(day, 'EEEE', { locale: fr })}
                        </p>
                        <p className="text-sm text-gray-500">
                          {hasInterventions 
                            ? `${dayInterventions.length} intervention${dayInterventions.length > 1 ? 's' : ''}`
                            : 'Libre'
                          }
                        </p>
                      </div>
                    </div>

                    {hasInterventions && (
                      <ChevronDown 
                        className={`w-5 h-5 text-gray-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`} 
                      />
                    )}
                  </button>

                  {/* Expanded Interventions */}
                  {isExpanded && hasInterventions && (
                    <div className="border-t border-gray-100 divide-y divide-gray-100">
                      {dayInterventions.map((intervention) => {
                        const startTime = intervention.date_planned
                          ? new Date(intervention.date_planned)
                          : null;
                        const endTime = startTime
                          ? addMinutes(startTime, intervention.estimated_duration_minutes || 60)
                          : null;
                        const statusColor = STATUS_COLORS[intervention.status] || STATUS_COLORS.nouveau;
                        const isChantier = intervention.intervention_type === 'chantier';
                        const interventionHref = isChantier
                          ? `/technician/chantier/${intervention.id}`
                          : `/technician/report/${intervention.id}`;

                        return (
                          <Link
                            key={intervention.id}
                            href={interventionHref}
                            className="flex items-start gap-3 p-4 active:bg-gray-50"
                          >
                            {/* Status indicator */}
                            <div className={`w-1 h-12 rounded-full ${statusColor} flex-shrink-0`} />

                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 text-sm text-gray-500 mb-1">
                                <Clock className="w-3.5 h-3.5" />
                                <span>
                                  {startTime ? format(startTime, 'HH:mm') : '--:--'}
                                  {endTime && ` - ${format(endTime, 'HH:mm')}`}
                                </span>
                                <span className={`px-1.5 py-0.5 rounded text-[10px] font-semibold ${isChantier ? 'bg-indigo-100 text-indigo-700' : 'bg-orange-100 text-orange-700'}`}>
                                  {isChantier ? '🏗️' : '🔧'}
                                </span>
                              </div>
                              <p className="font-medium text-gray-900 truncate">
                                {intervention.title}
                              </p>
                              {intervention.address && (
                                <p className="text-sm text-gray-500 truncate flex items-center gap-1 mt-1">
                                  <MapPin className="w-3.5 h-3.5 flex-shrink-0" />
                                  {intervention.address}
                                </p>
                              )}
                              {intervention.keys_info && (
                                <p className="text-sm text-amber-700 flex items-center gap-1 mt-1">
                                  <KeyRound className="w-3.5 h-3.5 flex-shrink-0" />
                                  {intervention.keys_info}
                                </p>
                              )}
                            </div>

                            <ChevronRight className="w-5 h-5 text-gray-300 flex-shrink-0" />
                          </Link>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

