'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { Menu, Search, Wrench, FileText, Mail, Building, Loader2, FilePlus, Package } from 'lucide-react';
import { ROLES } from '@/lib/constants';
import type { User } from '@/types/database';
import { cn } from '@/lib/utils';
import { NotificationBell } from './NotificationBell';
import { createClient } from '@/lib/supabase/client';

// Page titles
const pageTitles: Record<string, string> = {
  '/inbox': 'Boîte de réception',
  '/calendar': 'Calendrier',
  '/interventions': 'Interventions',
  '/reports': 'Rapports',
  '/reports/validate': 'Validation des rapports',
  '/invoices': 'Factures',
  '/quotes': 'Devis',
  '/products': 'Catalogue produits',
  '/admin/users': 'Gestion des utilisateurs',
  '/admin/regies': 'Gestion des régies',
  '/admin/settings': 'Paramètres',
  '/technician/today': "Mes interventions du jour",
  '/technician/week': 'Ma semaine',
};

interface SearchResult {
  id: string;
  label: string;
  sub: string;
  href: string;
}

interface SearchResults {
  interventions: SearchResult[];
  emails: SearchResult[];
  quotes: SearchResult[];
  invoices: SearchResult[];
  products: SearchResult[];
  regies: SearchResult[];
}

interface HeaderProps {
  user: User;
}

export function Header({ user }: HeaderProps) {
  const pathname = usePathname();
  const router = useRouter();
  const supabase = createClient();

  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SearchResults | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const getPageTitle = () => {
    if (pageTitles[pathname]) return pageTitles[pathname];
    for (const [path, title] of Object.entries(pageTitles)) {
      if (pathname.startsWith(path + '/')) return title;
    }
    return 'Tableau de bord';
  };

  const roleInfo = ROLES[user.role];

  const search = useCallback(async (term: string) => {
    if (term.trim().length < 2) {
      setResults(null);
      setIsOpen(false);
      return;
    }

    setIsLoading(true);
    const pattern = `%${term}%`;

    const [interventionsRes, emailsRes, quotesRes, invoicesRes, productsRes, regiesRes] = await Promise.all([
      supabase
        .from('interventions')
        .select('id, title, address, work_order_number, status')
        .or(`title.ilike."${pattern}",address.ilike."${pattern}",work_order_number.ilike."${pattern}"`)
        .limit(5)
        .returns<{ id: string; title: string; address: string; work_order_number: string | null; status: string }[]>(),
      supabase
        .from('email_inbox')
        .select('id, subject, from_name, from_email, received_at')
        .or(`subject.ilike."${pattern}",from_name.ilike."${pattern}"`)
        .limit(5)
        .returns<{ id: string; subject: string | null; from_name: string | null; from_email: string; received_at: string }[]>(),
      supabase
        .from('quotes')
        .select('id, quote_number, client_name, description, total_ttc')
        .or(`quote_number.ilike."${pattern}",client_name.ilike."${pattern}",description.ilike."${pattern}"`)
        .limit(5)
        .returns<{ id: string; quote_number: string | null; client_name: string; description: string | null; total_ttc: number }[]>(),
      supabase
        .from('invoices')
        .select('id, invoice_number, client_name, amount_total, status')
        .or(`invoice_number.ilike."${pattern}",client_name.ilike."${pattern}"`)
        .limit(5)
        .returns<{ id: string; invoice_number: string; client_name: string; amount_total: number; status: string }[]>(),
      supabase
        .from('products')
        .select('id, name, description, sku, category, price')
        .or(`name.ilike."${pattern}",description.ilike."${pattern}",sku.ilike."${pattern}"`)
        .limit(5)
        .returns<{ id: string; name: string; description: string | null; sku: string | null; category: string; price: number }[]>(),
      supabase
        .from('regies')
        .select('id, name')
        .ilike('name', pattern)
        .limit(5)
        .returns<{ id: string; name: string }[]>(),
    ]);

    setResults({
      interventions: (interventionsRes.data ?? []).map((i) => ({
        id: i.id,
        label: i.title,
        sub: i.work_order_number ? `#${i.work_order_number} — ${i.address}` : i.address,
        href: `/interventions/${i.id}`,
      })),
      emails: (emailsRes.data ?? []).map((e) => ({
        id: e.id,
        label: e.subject ?? '(sans objet)',
        sub: e.from_name ?? e.from_email,
        href: '/inbox',
      })),
      quotes: (quotesRes.data ?? []).map((q) => ({
        id: q.id,
        label: q.quote_number ? `Devis ${q.quote_number}` : 'Devis',
        sub: q.description ? `${q.client_name} — ${q.description}` : q.client_name,
        href: `/quotes/${q.id}`,
      })),
      invoices: (invoicesRes.data ?? []).map((i) => ({
        id: i.id,
        label: `Facture ${i.invoice_number}`,
        sub: `${i.client_name} — CHF ${i.amount_total.toFixed(2)}`,
        href: `/invoices/${i.id}`,
      })),
      products: (productsRes.data ?? []).map((p) => ({
        id: p.id,
        label: p.name,
        sub: p.sku ? `SKU: ${p.sku} — CHF ${p.price.toFixed(2)}` : `CHF ${p.price.toFixed(2)}`,
        href: '/products',
      })),
      regies: (regiesRes.data ?? []).map((r) => ({
        id: r.id,
        label: r.name,
        sub: 'Régie',
        href: '/admin/regies',
      })),
    });

    setIsOpen(true);
    setIsLoading(false);
  }, []);

  // Debounce
  useEffect(() => {
    if (query.trim().length < 2) {
      setResults(null);
      setIsOpen(false);
      return;
    }

    const timer = setTimeout(() => {
      search(query);
    }, 300);

    return () => clearTimeout(timer);
  }, [query, search]);

  // Close on click outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Close on route change
  useEffect(() => {
    setIsOpen(false);
    setQuery('');
  }, [pathname]);

  const handleSelect = (href: string) => {
    setIsOpen(false);
    setQuery('');
    router.push(href);
  };

  const totalResults = results
    ? results.interventions.length + results.emails.length + results.quotes.length + results.invoices.length + results.products.length + results.regies.length
    : 0;

  const categories: { key: keyof SearchResults; label: string; icon: React.ReactNode }[] = [
    { key: 'interventions', label: 'Interventions', icon: <Wrench className="w-4 h-4 text-gray-400" /> },
    { key: 'emails', label: 'Emails', icon: <Mail className="w-4 h-4 text-gray-400" /> },
    { key: 'quotes', label: 'Devis', icon: <FilePlus className="w-4 h-4 text-gray-400" /> },
    { key: 'invoices', label: 'Factures', icon: <FileText className="w-4 h-4 text-gray-400" /> },
    { key: 'products', label: 'Produits', icon: <Package className="w-4 h-4 text-gray-400" /> },
    { key: 'regies', label: 'Régies', icon: <Building className="w-4 h-4 text-gray-400" /> },
  ];

  return (
    <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-6 flex-shrink-0">
      {/* Left */}
      <div className="flex items-center gap-4">
        <button className="md:hidden p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-lg">
          <Menu className="w-5 h-5" />
        </button>
        <h1 className="text-lg font-semibold text-gray-900">{getPageTitle()}</h1>
      </div>

      {/* Right */}
      <div className="flex items-center gap-3">
        {/* Search */}
        <div className="hidden md:flex items-center">
          <div className="relative" ref={containerRef}>
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            {isLoading && (
              <Loader2 className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 animate-spin" />
            )}
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onFocus={() => { if (results && totalResults > 0) setIsOpen(true); }}
              placeholder="Rechercher..."
              autoComplete="off"
              autoCorrect="off"
              autoCapitalize="off"
              spellCheck={false}
              name="search-global-lx"
              id="search-global-lx"
              className="w-56 h-9 pl-9 pr-3 text-sm bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />

            {/* Dropdown */}
            {isOpen && results && (
              <div className="absolute top-full right-0 mt-1 w-96 bg-white rounded-lg shadow-lg border border-gray-200 z-50 overflow-hidden">
                {totalResults === 0 ? (
                  <div className="px-4 py-6 text-center text-sm text-gray-500">
                    Aucun résultat
                  </div>
                ) : (
                  <div className="max-h-96 overflow-y-auto py-1">
                    {categories.map(({ key, label, icon }) => {
                      const items = results[key];
                      if (items.length === 0) return null;
                      return (
                        <div key={key}>
                          <div className="px-3 py-2 flex items-center gap-2 text-xs font-semibold text-gray-400 uppercase tracking-wide">
                            {icon}
                            {label}
                          </div>
                          {items.map((item) => (
                            <button
                              key={item.id}
                              onClick={() => handleSelect(item.href)}
                              className="w-full text-left px-4 py-2 hover:bg-gray-50 transition-colors"
                            >
                              <p className="text-sm font-medium text-gray-900 truncate">{item.label}</p>
                              <p className="text-xs text-gray-500 truncate">{item.sub}</p>
                            </button>
                          ))}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* Role Badge */}
        <span className={cn('hidden sm:inline-flex px-2.5 py-1 rounded-md text-xs font-medium', roleInfo.color)}>
          {roleInfo.label}
        </span>

        {/* Notifications */}
        <NotificationBell />

        {/* User Avatar (mobile only - hidden when sidebar is visible) */}
        <div className="md:hidden w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
          <span className="text-xs font-semibold text-blue-600">
            {user.first_name.charAt(0)}{user.last_name.charAt(0)}
          </span>
        </div>
      </div>
    </header>
  );
}

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { cn } from '@/lib/utils';
import { ADMIN_ROUTES, ADMIN_ONLY_ROUTES, TECHNICIAN_ROUTES } from '@/lib/constants';
import type { User } from '@/types/database';
import {
  Inbox,
  Calendar,
  Wrench,
  ClipboardCheck,
  FileText,
  FilePlus,
  Package,
  Users,
  Building,
  Settings,
  CalendarCheck,
  History,
  HardHat,
  Clock,
  FileSignature,
  LogOut,
} from 'lucide-react';
import { createClient } from '@/lib/supabase/client';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { useNotificationCounts } from '@/hooks/useNotificationCounts';

// Icon mapping
const iconMap: Record<string, React.ComponentType<{ className?: string }>> = {
  'inbox': Inbox,
  'calendar': Calendar,
  'wrench': Wrench,
  'clipboard-check': ClipboardCheck,
  'file-text': FileText,
  'file-plus': FilePlus,
  'package': Package,
  'users': Users,
  'building': Building,
  'settings': Settings,
  'calendar-check': CalendarCheck,
  'hard-hat': HardHat,
  'history': History,
  'clock': Clock,
  'file-signature': FileSignature,
};

interface SidebarProps {
  user: User;
  className?: string;
}

export function Sidebar({ user, className }: SidebarProps) {
  const pathname = usePathname();
  const router = useRouter();
  const supabase = createClient();

  const isAdmin = user.role === 'admin';
  const isSecretary = user.role === 'secretary';
  const isTechnician = user.role === 'technician';
  const isStaff = isAdmin || isSecretary;
  const counts = useNotificationCounts();

  const mainRoutes = isTechnician ? TECHNICIAN_ROUTES : ADMIN_ROUTES;
  const adminRoutes = isAdmin ? ADMIN_ONLY_ROUTES : [];

  const badgeMap: Record<string, number> = isStaff
    ? {
        '/inbox': counts.inbox,
        '/reports/validate': counts.reportsToValidate,
        '/leave': counts.pendingLeave,
        '/chantiers': counts.chantierUpdates,
      }
    : {};

  const handleLogout = async () => {
    await supabase.auth.signOut();
    toast.success('Déconnexion réussie');
    router.push('/login');
    router.refresh();
  };

  return (
    <aside
      className={cn(
        'w-[260px] bg-white border-r border-gray-200 flex flex-col',
        className
      )}
    >
      {/* Logo */}
      <div className="h-16 flex items-center px-6 border-b border-gray-200">
        <Link href="/">
          <img
            src="https://yuumzhlvmqcbogqzuonp.supabase.co/storage/v1/object/public/photos/logo%20richoz/Logo%20Richoz%20Sanitaire%20(1).png"
            alt="Richoz Sanitaire"
            style={{ height: '40px' }}
          />
        </Link>
      </div>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto py-4">
        {/* Main Routes */}
        <div className="px-3 mb-6">
          <p className="px-3 mb-2 text-xs font-semibold text-gray-400 uppercase tracking-wide">
            {isTechnician ? 'Mon espace' : 'Gestion'}
          </p>
          <ul className="space-y-1">
            {mainRoutes.map((route) => {
              const Icon = iconMap[route.icon] || Wrench;
              const isActive = pathname === route.href || pathname.startsWith(route.href + '/');

              return (
                <li key={route.href}>
                  <Link
                    href={route.href}
                    className={cn(
                      'flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors',
                      isActive
                        ? 'bg-blue-50 text-blue-600'
                        : 'text-gray-700 hover:bg-gray-100'
                    )}
                  >
                    <Icon className={cn('w-5 h-5', isActive ? 'text-blue-600' : 'text-gray-400')} />
                    <span className="flex-1">{route.label}</span>
                    {(badgeMap[route.href] ?? 0) > 0 && (
                      <span className="w-5 h-5 flex items-center justify-center rounded-full bg-red-500 text-white text-xs font-semibold">
                        {badgeMap[route.href]}
                      </span>
                    )}
                  </Link>
                </li>
              );
            })}
          </ul>
        </div>

        {/* Admin Routes */}
        {adminRoutes.length > 0 && (
          <div className="px-3">
            <p className="px-3 mb-2 text-xs font-semibold text-gray-400 uppercase tracking-wide">
              Administration
            </p>
            <ul className="space-y-1">
              {adminRoutes.map((route) => {
                const Icon = iconMap[route.icon] || Settings;
                const isActive = pathname === route.href || pathname.startsWith(route.href + '/');

                return (
                  <li key={route.href}>
                    <Link
                      href={route.href}
                      className={cn(
                        'flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors',
                        isActive
                          ? 'bg-blue-50 text-blue-600'
                          : 'text-gray-700 hover:bg-gray-100'
                      )}
                    >
                      <Icon className={cn('w-5 h-5', isActive ? 'text-blue-600' : 'text-gray-400')} />
                      {route.label}
                    </Link>
                  </li>
                );
              })}
            </ul>
          </div>
        )}
      </nav>

      {/* User Section */}
      <div className="p-4 border-t border-gray-200">
        <Link
          href={isTechnician ? '/technician/profile' : '/profile'}
          className="flex items-center gap-3 mb-3 hover:bg-gray-50 rounded-lg p-1 -m-1 transition-colors"
          title="Mon profil"
        >
          <div className="w-9 h-9 bg-blue-100 rounded-full flex items-center justify-center">
            <span className="text-sm font-semibold text-blue-600">
              {user.first_name.charAt(0)}{user.last_name.charAt(0)}
            </span>
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-gray-900 truncate">
              {user.first_name} {user.last_name}
            </p>
            <p className="text-xs text-gray-500 truncate">{user.email}</p>
          </div>
        </Link>
        <button
          onClick={handleLogout}
          className="w-full flex items-center justify-center gap-2 px-3 py-2 text-sm text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
        >
          <LogOut className="w-4 h-4" />
          Déconnexion
        </button>
      </div>
    </aside>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import type { RealtimeChannel } from '@supabase/supabase-js';

interface NotificationCounts {
  inbox: number;
  reportsToValidate: number;
  pendingLeave: number;
  chantierUpdates: number;
}

export function useNotificationCounts() {
  const [counts, setCounts] = useState<NotificationCounts>({
    inbox: 0,
    reportsToValidate: 0,
    pendingLeave: 0,
    chantierUpdates: 0,
  });

  const supabase = createClient();

  const fetchCounts = useCallback(async () => {
    const { data: { user } } = await supabase.auth.getUser();
    const userId = user?.id;

    const [inboxRes, reportsRes, leaveRes, chantierRes] = await Promise.all([
      supabase
        .from('email_inbox')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'new'),
      supabase
        .from('reports')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'submitted'),
      supabase
        .from('leave_requests')
        .select('*', { count: 'exact', head: true })
        .eq('status', 'pending'),
      userId
        ? supabase
            .from('notifications')
            .select('*', { count: 'exact', head: true })
            .eq('recipient_id', userId)
            .eq('type', 'chantier_update')
            .eq('is_read', false)
        : Promise.resolve({ count: 0 }),
    ]);

    setCounts({
      inbox: inboxRes.count ?? 0,
      reportsToValidate: reportsRes.count ?? 0,
      pendingLeave: leaveRes.count ?? 0,
      chantierUpdates: chantierRes.count ?? 0,
    });
  }, []);

  useEffect(() => {
    fetchCounts();

    const channels: RealtimeChannel[] = [];

    const emailChannel = supabase
      .channel('notif-email_inbox')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'email_inbox' }, () => {
        fetchCounts();
      })
      .subscribe();
    channels.push(emailChannel);

    const reportsChannel = supabase
      .channel('notif-reports')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reports' }, () => {
        fetchCounts();
      })
      .subscribe();
    channels.push(reportsChannel);

    const leaveChannel = supabase
      .channel('notif-leave_requests')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'leave_requests' }, () => {
        fetchCounts();
      })
      .subscribe();
    channels.push(leaveChannel);

    const notifChannel = supabase
      .channel('notif-notifications')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, () => {
        fetchCounts();
      })
      .subscribe();
    channels.push(notifChannel);

    return () => {
      channels.forEach((ch) => supabase.removeChannel(ch));
    };
  }, [fetchCounts]);

  return counts;
}

'use client';

import { useEffect, useRef, useCallback } from 'react';
import { createClient } from '@/lib/supabase/client';
import type { RealtimeChannel, RealtimePostgresChangesPayload } from '@supabase/supabase-js';

type TableName = 'interventions' | 'reports' | 'email_inbox' | 'leave_requests';

interface UseRealtimeOptions<T> {
  table: TableName;
  filter?: string;
  onInsert?: (payload: T) => void;
  onUpdate?: (payload: T) => void;
  onDelete?: (payload: { id: string }) => void;
  enabled?: boolean;
}

/**
 * Hook for subscribing to Supabase Realtime changes
 * @example
 * useRealtime({
 *   table: 'interventions',
 *   filter: 'technician_id=eq.abc123',
 *   onInsert: (intervention) => console.log('New:', intervention),
 *   onUpdate: (intervention) => console.log('Updated:', intervention),
 * });
 */
export function useRealtime<T extends { id: string }>({
  table,
  filter,
  onInsert,
  onUpdate,
  onDelete,
  enabled = true,
}: UseRealtimeOptions<T>) {
  const supabase = createClient();
  const channelRef = useRef<RealtimeChannel | null>(null);

  const handleChange = useCallback(
    (payload: RealtimePostgresChangesPayload<T>) => {
      if (payload.eventType === 'INSERT' && onInsert) {
        onInsert(payload.new as T);
      } else if (payload.eventType === 'UPDATE' && onUpdate) {
        onUpdate(payload.new as T);
      } else if (payload.eventType === 'DELETE' && onDelete) {
        onDelete({ id: (payload.old as { id: string }).id });
      }
    },
    [onInsert, onUpdate, onDelete]
  );

  useEffect(() => {
    if (!enabled) return;

    const channelName = `realtime-${table}${filter ? `-${filter}` : ''}`;

    channelRef.current = supabase
      .channel(channelName)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table,
          filter,
        },
        handleChange
      )
      .subscribe();

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [table, filter, enabled, handleChange]);
}

/**
 * Hook for subscribing to intervention changes
 */
export function useInterventionsRealtime(
  options: Omit<UseRealtimeOptions<{ id: string }>, 'table'>
) {
  return useRealtime({ ...options, table: 'interventions' });
}

/**
 * Hook for subscribing to report changes
 */
export function useReportsRealtime(
  options: Omit<UseRealtimeOptions<{ id: string }>, 'table'>
) {
  return useRealtime({ ...options, table: 'reports' });
}

/**
 * Hook for subscribing to email inbox changes
 */
export function useEmailInboxRealtime(
  options: Omit<UseRealtimeOptions<{ id: string }>, 'table'>
) {
  return useRealtime({ ...options, table: 'email_inbox' });
}

'use client';

import { useEffect, useState } from 'react';
import { createClient } from '@/lib/supabase/client';
import type { User, UserRole } from '@/types/database';
import type { User as AuthUser } from '@supabase/supabase-js';

interface UseUserReturn {
  user: User | null;
  authUser: AuthUser | null;
  role: UserRole | null;
  isLoading: boolean;
  error: Error | null;
  isAdmin: boolean;
  isAdminOrSecretary: boolean;
  isTechnician: boolean;
  refetch: () => Promise<void>;
}

export function useUser(): UseUserReturn {
  const [user, setUser] = useState<User | null>(null);
  const [authUser, setAuthUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const supabase = createClient();

  const fetchUser = async () => {
    try {
      setIsLoading(true);
      setError(null);

      // Get authenticated user
      const { data: { user: auth }, error: authError } = await supabase.auth.getUser();

      if (authError) throw authError;

      if (!auth) {
        setAuthUser(null);
        setUser(null);
        return;
      }

      setAuthUser(auth);

      // Get user profile from our users table
      const { data: profile, error: profileError } = await supabase
        .from('users')
        .select('*')
        .eq('id', auth.id)
        .single();

      if (profileError) throw profileError;

      setUser(profile);
    } catch (err) {
      setError(err instanceof Error ? err : new Error('Erreur lors du chargement du profil'));
      setUser(null);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchUser();

    // Listen for auth state changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
          await fetchUser();
        } else if (event === 'SIGNED_OUT') {
          setUser(null);
          setAuthUser(null);
        }
      }
    );

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const role = user?.role ?? null;

  return {
    user,
    authUser,
    role,
    isLoading,
    error,
    isAdmin: role === 'admin',
    isAdminOrSecretary: role === 'admin' || role === 'secretary',
    isTechnician: role === 'technician',
    refetch: fetchUser,
  };
}
